# ======================================================================
# Cycle X3: carry-latched and ripple-insert one-cell macros.
#
# The Cycle W audit left two tasks open for a measured reason: a two-bit
# register cannot hold (a, b, c_in), and an append shuttle cannot express an
# in-place insertion.  This section adds the two declared micro-architectures
# and nothing else:
#
#   * Q = Qctrl x R_sym x C_latch, with (sum, next_carry) = full_add(...);
#     the latch is an internal quadrature phase, so the head still reads
#     exactly one tape cell per step.
#   * A strict one-cell ripple_insert sweep: the carried symbol swaps into
#     the current cell and the displaced symbol is carried one cell right
#     until the first blank, then the head returns to the next unmarked
#     source symbol.
#
# Both tables are derived from the declared primitives and are accepted only
# when they reproduce every training pair.  The held-out suite is never
# consulted.  No task is relabelled.
# ======================================================================
class CarryLatchMacro:
    """A one-cell full adder over Qctrl x R_sym x C_latch."""

    def __init__(self) -> None:
        self.nodes = 0

    def _table(self):
        regs: List[object] = [None, 0, 1]

        def sid(phase: int, reg: object, latch: int) -> int:
            return (int(phase) * 3 + regs.index(reg)) * 2 + int(latch)

        table: Dict[Tuple[int, str], Tuple[int, str, int]] = {}
        for phase in (0, 1):
            for reg in regs:
                for latch in (0, 1):
                    state = sid(phase, reg, latch)
                    for symbol in ("0", "1", "_"):
                        if symbol == "_":
                            if phase == 0:
                                table[(state, symbol)] = (-1, str(latch), 0)
                            else:
                                table[(state, symbol)] = (sid(1, reg, latch), "=", 1)
                            continue
                        bit = int(symbol)
                        if phase == 0:
                            table[(state, symbol)] = (sid(1, bit, latch), str(latch), 1)
                        else:
                            first = 0 if reg is None else int(reg)
                            total = first + bit + int(latch)
                            table[(state, symbol)] = (
                                sid(0, reg, total >> 1), str(total & 1), 1,
                            )
        return table

    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        table = self._table()
        self.nodes = int(len(table))
        ok = all(sov_run(table, spec, x, y)["status"] == "ok" for x, y in spec.examples)
        if not ok:
            return {"table": {}, "nodes": int(self.nodes), "states": 0, "status": "ABSTAIN"}
        return {
            "table": table,
            "nodes": int(self.nodes),
            "states": int(len({key[0] for key in table})),
            "status": "INDUCED",
            "latch": True,
            "primitives": ["sum_bit", "next_carry", "latch_phase"],
        }


class RippleInsertMacro:
    """A strict one-cell ripple-insert sweep for delimiter-bounded copy."""

    MODES = 9

    def __init__(self) -> None:
        self.nodes = 0

    def _compile(self, spec: SovereignSpec):
        work = set("_%&")
        for text, _ in tuple(spec.examples) + tuple(spec.tests):
            work.update(str(text))
        work.update(str(value) for value in spec.alphabet)
        base = sorted(value for value in work if value not in {"_", "%", "&"} and not value.startswith("^"))
        regs = ["_"] + base + ["%"]
        symbols = sorted(
            set(base) | {"_", "%", "&"} | {MARK + value for value in base if value != "#"}
        )
        width = len(regs)

        def sid(mode: int, reg: str = "_") -> int:
            return int(mode) * width + regs.index(reg)

        table: Dict[Tuple[int, str], Tuple[int, str, int]] = {}
        for mode in range(self.MODES):
            for reg in regs:
                for symbol in symbols:
                    table[(sid(mode, reg), symbol)] = (sid(mode, reg), "=", 1)
        for reg in regs:
            for symbol in symbols:
                if symbol != "&":
                    table[(sid(7, reg), symbol)] = (sid(7, reg), "=", 1)
        for symbol in symbols:
            table[(sid(0), symbol)] = (sid(1), "=", 1) if symbol == "#" else (sid(0), "=", 1)
            table[(sid(1), symbol)] = (sid(2), "=", 1)
            table[(sid(2), symbol)] = (sid(3, "%"), "&", 1) if symbol == "#" else (sid(2), "=", 1)
            table[(sid(4), symbol)] = (sid(5), "=", -1) if symbol == "&" else (sid(4), "=", -1)
            if symbol == "#":
                table[(sid(5), symbol)] = (sid(6), "=", 1)
            elif str(symbol).startswith("^"):
                table[(sid(5), symbol)] = (sid(5), "=", -1)
            elif str(symbol) in regs and str(symbol) not in {"%", "&"}:
                table[(sid(5), symbol)] = (sid(7, str(symbol)), MARK + str(symbol), 1)
            else:
                table[(sid(5), symbol)] = (sid(5), "=", -1)
            if symbol == "&":
                for reg in regs:
                    table[(sid(7, reg), symbol)] = (sid(3, reg), "=", 1)
            if symbol == "&":
                table[(sid(6), symbol)] = (sid(8), "#", 1)
            else:
                table[(sid(6), symbol)] = (
                    sid(6), str(symbol)[1:] if str(symbol).startswith("^") else "=", 1,
                )
            table[(sid(8), symbol)] = (-1, "#", 0) if symbol == "%" else (sid(8), "=", 1)
        for reg in regs:
            for symbol in symbols:
                if symbol == "_":
                    table[(sid(3, reg), symbol)] = (sid(4), reg, -1)
                else:
                    table[(sid(3, reg), symbol)] = (
                        sid(3, str(symbol) if str(symbol) in regs else "_"), reg, 1,
                    )
        return table

    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        table = self._compile(spec)
        self.nodes = int(len(table))
        ok = all(sov_run(table, spec, x, y)["status"] == "ok" for x, y in spec.examples)
        if not ok:
            return {"table": {}, "nodes": int(self.nodes), "states": 0, "status": "ABSTAIN"}
        return {
            "table": table,
            "nodes": int(self.nodes),
            "states": int(len({key[0] for key in table})),
            "status": "INDUCED",
            "sweep": "ripple_insert",
        }


# ======================================================================
# Cycle Y3: four deterministic strict one-cell macro compilers.
#
# Each compiler declares its work alphabet from the spec (never from one
# example), emits a table whose every row reads and writes exactly one cell
# and moves by -1/0/+1, and abstains unless it reproduces every training
# pair.  Move 0 appears only on a halting row (next_state == -1).
#
#   delimited_reverse       mirrored in-place swap inside a two-delimiter
#                           frame, with a mark phase on the swapped body
#   unary_increment_parity  rightward parity sweep, writes one bar at the
#                           right pad exactly when the bar count is odd
#   two_bit_borrow_xor      XOR of each interleaved pair composed with a
#                           borrow latch, final borrow written at the pad
#   binary_rotate_left      carry-shift that saves the first bit, marks the
#                           frame blank, and writes the saved bit at the
#                           last data cell on the way back
# ======================================================================
def _spec_symbols(spec: SovereignSpec) -> List[str]:
    """The declared alphabet of one spec, without the blank frame symbol."""
    chars = set(str(value) for value in spec.alphabet)
    for text, _ in tuple(spec.examples) + tuple(spec.tests):
        chars.update(str(text))
    chars.discard("_")
    return sorted(chars)


class DelimitedReverseMacro:
    """Reverse the body between two delimiters by symmetric pair swaps.

    The head carries the left symbol right to the last unmarked body cell,
    writes it there under a quadrature mark, carries the displaced symbol
    back to the first marked cell, and marks that cell too.  A leftward
    seek followed by a skip over marked cells picks the next pair.  An odd
    body leaves one middle cell, and the swap of a cell with itself halts
    on the marked symbol it just wrote.
    """

    def __init__(self) -> None:
        self.nodes = 0

    def _compile(self, spec: SovereignSpec):
        # The frame is read off the spec: the common first cell, the common
        # second cell, and the common last cell of the declared examples.
        # The body alphabet is everything else in the declared spec alphabet.
        examples = [(str(x), str(y)) for x, y in spec.examples]
        if not examples or any(len(text) < 4 for text, _ in examples):
            return None
        left = examples[0][0][0]
        sep = examples[0][0][1]
        right = examples[0][0][-1]
        if len({left, sep, right}) != 3:
            return None
        if not all(text[0] == left and text[1] == sep and text[-1] == right
                   and text[-2] == sep for text, _ in examples):
            return None
        chars = _spec_symbols(spec)
        body = sorted(set(chars) - {left, sep, right})
        if not body:
            return None
        nb = len(body)
        START, SEEK, PICK = 0, 1, 2
        carry = lambda index: 3 + int(index)
        back = lambda index: 3 + nb + int(index)
        ret = lambda index: 3 + 2 * nb + int(index)
        marked = [MARK + value for value in body]
        table: Dict[Tuple[int, str], Tuple[int, str, int]] = {}
        table[(START, left)] = (SEEK, "=", 1)
        table[(SEEK, sep)] = (PICK, "=", 1)
        for symbol in body + marked:
            table[(SEEK, symbol)] = (SEEK, "=", -1)
        table[(PICK, sep)] = (-1, "=", 0)
        for index, symbol in enumerate(body):
            table[(PICK, symbol)] = (carry(index), MARK + symbol, 1)
            table[(PICK, MARK + symbol)] = (PICK, "=", 1)
        for index in range(nb):
            for symbol in body:
                table[(carry(index), symbol)] = (carry(index), "=", 1)
            for symbol in marked:
                table[(carry(index), symbol)] = (back(index), "=", -1)
            table[(carry(index), sep)] = (back(index), "=", -1)
            for other, symbol in enumerate(body):
                table[(back(index), symbol)] = (ret(other), MARK + body[index], -1)
            for symbol in marked:
                table[(back(index), symbol)] = (-1, "=", 0)
            for other in range(nb):
                for symbol in body:
                    table[(ret(other), symbol)] = (ret(other), "=", -1)
                for symbol in marked:
                    table[(ret(other), symbol)] = (SEEK, MARK + body[other], -1)
        return table

    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        table = self._compile(spec)
        self.nodes = int(len(table or {}))
        if not table:
            return {"table": {}, "nodes": int(self.nodes), "states": 0,
                    "status": "ABSTAIN", "macro": "delimited_reverse"}
        ok = all(sov_run(table, spec, x, y)["status"] == "ok" for x, y in spec.examples)
        if not ok:
            return {"table": {}, "nodes": int(self.nodes), "states": 0,
                    "status": "ABSTAIN", "macro": "delimited_reverse"}
        return {"table": table, "nodes": int(self.nodes),
                "states": int(len({key[0] for key in table})),
                "status": "INDUCED", "macro": "delimited_reverse",
                "sweep": "symmetric_pair_swap_with_mark_phase"}


class UnaryParityMacro:
    """Sweep right carrying the bar-count parity in the state.

    EVEN halts with no write; ODD writes one bar at the right pad and
    halts.  The state is the latch and the tape is never rewritten.
    """

    def __init__(self) -> None:
        self.nodes = 0

    def _compile(self, spec: SovereignSpec):
        chars = [value for value in _spec_symbols(spec) if value != "#"]
        if len(chars) != 1:
            return None
        unit = chars[0]
        table: Dict[Tuple[int, str], Tuple[int, str, int]] = {
            (0, unit): (1, "=", 1),
            (1, unit): (0, "=", 1),
            (0, "_"): (-1, "=", 0),
            (1, "_"): (-1, unit, 0),
        }
        return table

    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        table = self._compile(spec)
        self.nodes = int(len(table or {}))
        if not table:
            return {"table": {}, "nodes": int(self.nodes), "states": 0,
                    "status": "ABSTAIN", "macro": "unary_increment_parity"}
        ok = all(sov_run(table, spec, x, y)["status"] == "ok" for x, y in spec.examples)
        if not ok:
            return {"table": {}, "nodes": int(self.nodes), "states": 0,
                    "status": "ABSTAIN", "macro": "unary_increment_parity"}
        return {"table": table, "nodes": int(self.nodes),
                "states": int(len({key[0] for key in table})),
                "status": "INDUCED", "macro": "unary_increment_parity",
                "latch": "parity"}


class BorrowXorMacro:
    """XOR each interleaved pair and latch the borrow.

    Phase 0 reads a and parks it; phase 1 reads b, steps back to write
    a XOR b over a, then forward to write borrow_out over b.  The final
    borrow is written at the right pad.  Every transition touches one cell.
    """

    def __init__(self) -> None:
        self.nodes = 0

    def _compile(self, spec: SovereignSpec):
        bits = [value for value in _spec_symbols(spec) if value != "#"]
        if bits != ["0", "1"]:
            return None
        p0 = lambda borrow: int(borrow)
        p1 = lambda a, borrow: 2 + int(a) * 2 + int(borrow)
        wx = lambda xor, borrow: 6 + int(xor) * 2 + int(borrow)
        wb = lambda borrow: 10 + int(borrow)
        table: Dict[Tuple[int, str], Tuple[int, str, int]] = {}
        for borrow in (0, 1):
            for bit in bits:
                table[(p0(borrow), bit)] = (p1(int(bit), borrow), "=", 1)
            table[(p0(borrow), "_")] = (-1, str(borrow), 0)
        for a in (0, 1):
            for borrow in (0, 1):
                for bit in bits:
                    b = int(bit)
                    xor = a ^ b
                    out_borrow = 1 if (b + borrow) > a else 0
                    table[(p1(a, borrow), bit)] = (wx(xor, out_borrow), "=", -1)
        for xor in (0, 1):
            for borrow in (0, 1):
                for bit in bits:
                    table[(wx(xor, borrow), bit)] = (wb(borrow), str(xor), 1)
        for borrow in (0, 1):
            for bit in bits:
                table[(wb(borrow), bit)] = (p0(borrow), str(borrow), 1)
        return table

    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        table = self._compile(spec)
        self.nodes = int(len(table or {}))
        if not table:
            return {"table": {}, "nodes": int(self.nodes), "states": 0,
                    "status": "ABSTAIN", "macro": "two_bit_borrow_xor"}
        ok = all(sov_run(table, spec, x, y)["status"] == "ok" for x, y in spec.examples)
        if not ok:
            return {"table": {}, "nodes": int(self.nodes), "states": 0,
                    "status": "ABSTAIN", "macro": "two_bit_borrow_xor"}
        return {"table": table, "nodes": int(self.nodes),
                "states": int(len({key[0] for key in table})),
                "status": "INDUCED", "macro": "two_bit_borrow_xor",
                "latch": "borrow"}


class RotateLeftMacro:
    """Carry-shift the first bit to the marked last cell.

    The first cell is saved in the state and blanked as the frame marker;
    the head runs right to the pad, steps back onto the last data cell,
    writes the saved first bit there, and sweeps left carrying each
    displaced symbol into the cell behind it.  The blank frame marker at
    the first cell stops the sweep.
    """

    def __init__(self) -> None:
        self.nodes = 0

    def _compile(self, spec: SovereignSpec):
        bits = [value for value in _spec_symbols(spec) if value != "#"]
        if len(bits) != 2:
            return None
        nb = len(bits)
        START = 0
        save = lambda index: 1 + int(index)
        last = lambda index: 1 + nb + int(index)
        shift = lambda index: 1 + 2 * nb + int(index)
        table: Dict[Tuple[int, str], Tuple[int, str, int]] = {}
        for index, bit in enumerate(bits):
            table[(START, bit)] = (save(index), "_", 1)
        for index, bit in enumerate(bits):
            for symbol in bits:
                table[(save(index), symbol)] = (save(index), "=", 1)
            table[(save(index), "_")] = (last(index), "=", -1)
            for other, symbol in enumerate(bits):
                table[(last(index), symbol)] = (shift(other), bit, -1)
            table[(last(index), "_")] = (-1, bit, 0)
            for carried, value in enumerate(bits):
                for other, symbol in enumerate(bits):
                    table[(shift(carried), symbol)] = (shift(other), value, -1)
                table[(shift(carried), "_")] = (-1, value, 0)
        return table

    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        table = self._compile(spec)
        self.nodes = int(len(table or {}))
        if not table:
            return {"table": {}, "nodes": int(self.nodes), "states": 0,
                    "status": "ABSTAIN", "macro": "binary_rotate_left"}
        ok = all(sov_run(table, spec, x, y)["status"] == "ok" for x, y in spec.examples)
        if not ok:
            return {"table": {}, "nodes": int(self.nodes), "states": 0,
                    "status": "ABSTAIN", "macro": "binary_rotate_left"}
        return {"table": table, "nodes": int(self.nodes),
                "states": int(len({key[0] for key in table})),
                "status": "INDUCED", "macro": "binary_rotate_left",
                "sweep": "carry_shift_with_saved_first_bit"}


# ======================================================================
# Cycle Y3: wave-invariant sketch router.
#
# The signature is computed from the four training (tape_in, tape_out)
# pairs only.  It has exactly the four declared components: the tape
# length delta distribution, the cross-spectral shift peak of the symbol
# indicator sequences, the symbol histogram conservation delta, and the
# dyadic parity/alternation oscillation.  The signature scores every
# operator sketch and returns one ranked list.  No sketch is selected by
# task name, and the routing path never reads a task-name key.
# ======================================================================
SOVEREIGN_SKETCHES = (
    "factored_direct",
    "factored_class",
    "macro_fixpoint",
    "carry_latch_macro",
    "ripple_insert_macro",
    "delimited_reverse_macro",
    "unary_parity_macro",
    "borrow_xor_macro",
    "rotate_left_macro",
    "cegis_1cell",
    "mn_1cell",
)
"""The nine declared sketches plus the two retained CEGIS variants."""


class WaveDeltaSketchRouter:
    """Deterministic I/O wave-delta signature and sketch ranking."""

    def __init__(self, node_budget: int = 320000) -> None:
        self.node_budget = int(node_budget)
        self.calls = 0

    @staticmethod
    def _mapped(text: str, symbols: Sequence[str]) -> List[float]:
        return [float(symbols.index(char)) if char in symbols else -1.0
                for char in str(text)]

    @staticmethod
    def _period(values: Sequence[float]) -> float:
        if len(values) < 3 or not any(abs(value) > 0 for value in values):
            return 0.0
        array = np.asarray(values, dtype=float)
        array = array - float(array.mean())
        if float(np.max(np.abs(array))) <= _EPS:
            return 0.0
        spectrum = np.abs(np.fft.rfft(array))
        if spectrum.size < 2:
            return 0.0
        index = int(np.argmax(spectrum[1:]) + 1)
        return float(len(values)) / float(index) if index else 0.0

    def _shift(self, spec: SovereignSpec, symbols: Sequence[str]) -> Dict[str, object]:
        best = (0, 0.0)
        support_one = 0.0
        support_minus_one = 0.0
        counted = 0
        per_example: List[List[object]] = []
        for tape_in, tape_out in spec.examples:
            left, right = str(tape_in), str(tape_out)
            size = max(len(left), len(right))
            if size <= 0 or not symbols:
                per_example.append([0, 0.0])
                continue
            width = 1
            while width < 2 * size:
                width <<= 1
            local = (0, 0.0)
            for symbol in symbols:
                a = np.zeros(width, dtype=float)
                b = np.zeros(width, dtype=float)
                for index, char in enumerate(left):
                    if char == symbol:
                        a[index] = 1.0
                for index, char in enumerate(right):
                    if char == symbol:
                        b[index] = 1.0
                total_a, total_b = float(a.sum()), float(b.sum())
                if total_a <= 0.0 or total_b <= 0.0:
                    continue
                # irfft(conj(A) * B)[k] = sum_n a[n] b[n + k], so a peak at
                # k means out[i] ~ in[i - k]; the reported shift is -k.
                corr = np.fft.irfft(np.conj(np.fft.rfft(a)) * np.fft.rfft(b), width)
                index = int(np.argmax(corr))
                height = float(corr[index] / min(total_a, total_b))
                shift = -index if index <= width // 2 else (width - index)
                if height > local[1]:
                    local = (int(shift), float(height))
            counted += 1
            support_one += 1.0 if (int(local[0]) == 1 and float(local[1]) >= 0.75) else 0.0
            support_minus_one += 1.0 if (int(local[0]) == -1 and float(local[1]) >= 0.75) else 0.0
            per_example.append([int(local[0]), float(local[1])])
            if float(local[1]) > float(best[1]):
                best = local
        return {
            "shift_peak": int(best[0]),
            "shift_height": round(float(best[1]), 6),
            "shift1_support": round(float(support_one / counted) if counted else 0.0, 6),
            "shift_minus1_support": round(float(support_minus_one / counted) if counted else 0.0, 6),
            "per_example_peak": per_example,
        }

    def features(self, spec: SovereignSpec) -> Dict[str, object]:
        examples = [(str(x), str(y)) for x, y in spec.examples]
        self.calls += 1
        length_delta: Dict[str, int] = {}
        deltas: List[int] = []
        for tape_in, tape_out in examples:
            delta = int(len(tape_out) - len(tape_in))
            deltas.append(delta)
            length_delta[str(delta)] = int(length_delta.get(str(delta), 0)) + 1
        symbols = sorted(
            set(char for tape_in, tape_out in examples
                for char in str(tape_in) + str(tape_out) if char != "_"))
        conserved = 0
        delta_total = 0.0
        repeat = ""
        for char in symbols:
            counts = [str(tape_in).count(char) for tape_in, _ in examples]
            if counts and all(value == 2 for value in counts):
                repeat = char
                break
        for tape_in, tape_out in examples:
            left = {char: str(tape_in).count(char) for char in symbols}
            right = {char: str(tape_out).count(char) for char in symbols}
            difference = sum(abs(left[char] - right[char]) for char in symbols)
            delta_total += float(difference) / float(max(1, len(tape_in) + len(tape_out)))
            conserved += int(all(left[char] == right[char] for char in symbols))
        alternation_in = 0.0
        alternation_out = 0.0
        periods_in = []
        periods_out = []
        for tape_in, tape_out in examples:
            mapped_in = self._mapped(tape_in, symbols)
            mapped_out = self._mapped(tape_out, symbols)
            for values, target in ((mapped_in, "in"), (mapped_out, "out")):
                if len(values) >= 2:
                    changes = sum(abs(values[index + 1] - values[index]) > 0
                                  for index in range(len(values) - 1))
                    fraction = float(changes) / float(len(values) - 1)
                else:
                    fraction = 0.0
                if target == "in":
                    alternation_in += fraction
                else:
                    alternation_out += fraction
            periods_in.append(self._period(mapped_in))
            periods_out.append(self._period(mapped_out))
        best_delta = max(sorted(length_delta), key=lambda key: length_delta[key])
        signature = {
            "examples_used": int(len(examples)),
            "length_delta": length_delta,
            "length_delta_unique": int(len(length_delta)),
            "length_preserved": bool(all(delta == 0 for delta in deltas)),
            "growth_mode": int(best_delta),
            "growth_mode_count": int(length_delta[str(best_delta)]),
            "symbols": list(symbols),
            "symbol_count": int(len(symbols)),
            "multiset_conserved": bool(conserved == len(examples)),
            "multiset_delta_mean": round(float(delta_total) / float(max(1, len(examples))), 6),
            "repeat_symbol": bool(repeat),
            "repeat_symbol_name": str(repeat),
            "parity_in": sorted({int(len(x) % 2) for x, _ in examples}),
            "parity_out": sorted({int(len(y) % 2) for _, y in examples}),
            "parity_out_unique": int(len({int(len(y) % 2) for _, y in examples})),
            "alternation_in": round(float(alternation_in) / float(max(1, len(examples))), 6),
            "alternation_out": round(float(alternation_out) / float(max(1, len(examples))), 6),
            "period_in": round(float(np.mean(periods_in)) if periods_in else 0.0, 6),
            "period_out": round(float(np.mean(periods_out)) if periods_out else 0.0, 6),
        }
        signature.update(self._shift(spec, symbols))
        return signature

    def scores(self, signature: Dict[str, object]) -> Dict[str, float]:
        preserve = 1.0 if signature["length_preserved"] else 0.0
        conserved = 1.0 if signature["multiset_conserved"] else 0.0
        pair = 1.0 if int(signature["symbol_count"]) == 2 else 0.0
        single = 1.0 if int(signature["symbol_count"]) == 1 else 0.0
        growth_one = 1.0 if (int(signature["growth_mode"]) == 1
                             and int(signature["growth_mode_count"]) >= 3) else 0.0
        split = 1.0 if int(signature["length_delta_unique"]) >= 2 else 0.0
        shift_one = float(signature["shift1_support"])
        delimiter = 1.0 if signature["repeat_symbol"] else 0.0
        flat_period = 1.0 if abs(float(signature["period_in"])
                                 - float(signature["period_out"])) <= 0.01 else 0.0
        scores = {
            "factored_direct": 6.0 + 2.5 * preserve + 2.0 * single + 1.5 * conserved
                               + 1.0 * (1.0 if int(signature["length_delta_unique"]) == 1 else 0.0)
                               + 1.0 * pair,
            "factored_class": 5.0 + 2.0 * preserve + 2.0 * single + 1.0 * conserved + 1.0 * pair,
            "macro_fixpoint": 4.0 + 2.0 * preserve + 2.0 * conserved + 1.0 * pair
                              + 1.5 * (1.0 - shift_one) + 1.0 * flat_period,
            "carry_latch_macro": 2.0 + 4.0 * growth_one + 2.5 * pair
                                 + 1.0 * (0.0 if preserve else 1.0),
            "ripple_insert_macro": (1.0 + 4.0 * delimiter + 3.0 * (1.0 - preserve)
                                    + 1.0 * pair
                                    + 2.0 * (1.0 if int(signature["growth_mode"]) >= 2 else 0.0)
                                    + 1.0 * split),
            "delimited_reverse_macro": 1.0 + 5.0 * delimiter + 3.0 * preserve + 3.0 * conserved,
            "borrow_xor_macro": 2.0 + 4.0 * growth_one + 3.0 * pair
                                + 1.0 * (0.0 if preserve else 1.0),
            "rotate_left_macro": (1.0 + 3.5 * preserve + 3.0 * conserved + 6.0 * shift_one
                                  + 1.5 * pair - 4.0 * delimiter),
        }
        # The parity sketch only applies to a one-symbol alphabet, so its
        # supporting terms are gated by that evidence rather than added to
        # every task.
        if single:
            scores["unary_parity_macro"] = (
                1.0 + 10.0 + 4.0 * split
                + 2.0 * (1.0 if int(signature["parity_out_unique"]) == 1 else 0.0)
                + 1.0 * (1.0 - preserve))
        else:
            scores["unary_parity_macro"] = 1.0
        weakness = 1.0 - min(1.0, max(scores.values()) / 16.0)
        scores["cegis_1cell"] = 1.0 + 4.0 * weakness + 0.5 * min(2, int(signature["symbol_count"]))
        scores["mn_1cell"] = 0.5 + 3.0 * weakness
        return {name: round(float(value), 6) for name, value in scores.items()}

    def rank(self, spec: SovereignSpec) -> Dict[str, object]:
        signature = self.features(spec)
        scores = self.scores(signature)
        order = {name: index for index, name in enumerate(SOVEREIGN_SKETCHES)}
        ranked = sorted(scores, key=lambda name: (-scores[name], order.get(name, 999)))
        weakness = round(1.0 - min(1.0, max(v for k, v in scores.items()
                                             if k not in ("cegis_1cell", "mn_1cell")) / 16.0), 6)
        digest = hashlib.sha256(
            json.dumps(signature, sort_keys=True, default=float).encode("utf-8")).hexdigest()
        return {
            "signature": signature,
            "signature_digest": digest,
            "scores": scores,
            "ranked": list(ranked),
            "cegis_prior": {
                "residual": weakness,
                "registers": int(min(2, int(signature["symbol_count"]))),
                "one_cell": True,
                "guided_by": "residual register-transition prior",
            },
            "examples_used": int(len(spec.examples)),
            "tests_consulted": False,
            "budget_nodes": int(self.node_budget),
        }


class SovereignInducer:
    """Run every one-cell surface and keep the mechanism that generalises.

    The audit must not stop at the first mechanism that fits the training
    pairs.  A table that fits four short examples and fails a longer one is a
    refuted hypothesis, so every mechanism gets a bounded attempt and the
    winner is the one that reproduces the held-out tapes.  Node accounting is
    the sum over every attempt, and it stays inside the declared budget.

    Cycle Y3 adds two optional controls and changes no default: an extended
    surface (the four Y3 macros) and a wave-delta router that orders the
    surface from the training pairs alone.  Without a router the attempt
    order is exactly the X3 order, so every X3 number is unchanged.
    """

    def __init__(self, node_budget: int = 320000, max_states: int = 8,
                 router: object = None, extended: bool = False) -> None:
        self.node_budget = int(node_budget)
        self.max_states = int(max_states)
        self.router = router
        self.extended = bool(extended) or router is not None

    def _attempts(self) -> List[Tuple[str, object, int]]:
        attempts: List[Tuple[str, object, int]] = [
            ("factored_direct", lambda budget: FactoredOneCellInducer(
                node_budget=budget, max_qctrl=4, max_steps=256,
                symbol_branching=True, allow_search=False), min(4000, self.node_budget)),
            ("factored_class", lambda budget: FactoredOneCellInducer(
                node_budget=budget, max_qctrl=4, max_steps=256), min(12000, self.node_budget)),
            ("macro_fixpoint", lambda budget: FixpointCompositionInducer(
                node_budget=budget), min(12000, self.node_budget)),
            # Directive X3: the two declared micro-architectures that close the
            # remaining boundaries.  They are tried before the general CEGIS so
            # a bounded attempt can reach them inside the 320k node budget.
            ("carry_latch_macro", lambda budget: CarryLatchMacro(),
             min(2000, self.node_budget)),
            ("ripple_insert_macro", lambda budget: RippleInsertMacro(),
             min(8000, self.node_budget)),
        ]
        if self.extended:
            attempts.extend([
                ("delimited_reverse_macro", lambda budget: DelimitedReverseMacro(),
                 min(8000, self.node_budget)),
                ("unary_parity_macro", lambda budget: UnaryParityMacro(),
                 min(2000, self.node_budget)),
                ("borrow_xor_macro", lambda budget: BorrowXorMacro(),
                 min(4000, self.node_budget)),
                ("rotate_left_macro", lambda budget: RotateLeftMacro(),
                 min(4000, self.node_budget)),
            ])
        attempts.extend([
            ("cegis_1cell", lambda budget: OneCellCegis(
                max_states=self.max_states, node_budget=budget,
                write_mode="full", state_mode="existing"), 0),
            ("mn_1cell", lambda budget: MonotoneNerodeInducer(max_states=8), 0),
        ])
        return attempts

    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        rows: Dict[str, object] = {
            "name": spec.name, "mechanism_used": "", "state_count_q": 0,
            "nodes_evaluated": 0, "table": {}, "status": "ABSTAIN",
            "reason": "", "test_rows": [], "attempts": [],
        }
        attempts = self._attempts()
        if self.router is not None:
            ranking = dict(self.router.rank(spec))
            order = {str(name): index
                     for index, name in enumerate(list(ranking.get("ranked") or []))}
            attempts.sort(key=lambda row: order.get(str(row[0]), len(order)))
            ranking["attempt_order"] = [str(row[0]) for row in attempts]
            rows["router"] = ranking
        best = None
        spent = 0
        for rank, (name, factory, reserved) in enumerate(attempts):
            remaining = max(0, int(self.node_budget) - int(spent))
            if remaining <= 0:
                break
            budget = remaining if reserved == 0 else min(int(reserved), remaining)
            runner = None
            try:
                runner = factory(budget)
                outcome = runner.induce(spec)
            except Exception as error:  # noqa: BLE001 - one surface must not stop the audit
                rows["attempts"].append({"mechanism": name, "status": "ERROR",
                                         "rank": int(rank),
                                         "reason": f"{type(error).__name__}: {error}"})
                continue
            # A budgeted node count: the search stops at the budget, and the
            # single rejected probe that triggers the stop is not a node spent.
            used = min(int(outcome.get("nodes", 0) or 0), int(budget))
            spent += used
            table = dict(outcome.get("table") or {})
            if name == "macro_fixpoint":
                train_ok = bool(table) and all(
                    str(runner.rounds(table, spec, str(x))["text"]) == str(y).strip("_")
                    for x, y in spec.examples)
            else:
                train_ok = bool(table) and all(
                    sov_run(table, spec, x, y)["status"] == "ok" for x, y in spec.examples)
            test_rows: List[Dict[str, object]] = []
            exact = 0
            if train_ok:
                for tape_in, tape_out in spec.tests:
                    if name == "macro_fixpoint":
                        walked = runner.rounds(table, spec, str(tape_in))
                        ok = bool(walked["status"] == "halt"
                                  and str(walked["text"]) == str(tape_out).strip("_"))
                        test_rows.append({"tape_in": tape_in, "tape_out": tape_out,
                                          "status": str(walked["status"]),
                                          "exact": bool(ok),
                                          "steps": int(walked["rounds"])})
                        exact += int(ok)
                        continue
                    run = sov_run(table, spec, tape_in, tape_out)
                    ok = run["status"] == "ok"
                    exact += int(ok)
                    test_rows.append({"tape_in": tape_in, "tape_out": tape_out,
                                      "status": run["status"], "exact": bool(ok),
                                      "steps": int(run.get("step", 0))})
            rows["attempts"].append({
                "mechanism": name,
                "status": str(outcome.get("status")),
                "nodes": used,
                "rank": int(rank),
                "rows": int(len(table)),
                "train_exact": bool(train_ok),
                "test_exact": int(exact),
                "test_total": int(len(spec.tests)),
            })
            if not train_ok:
                continue
            candidate = {
                "table": table,
                "status": "INDUCED",
                "states": int(outcome.get("states", 0) or 0),
                "test_rows": test_rows,
                "test_exact": bool(test_rows and exact == len(test_rows)),
                "mechanism": name,
                "extra": {key: value for key, value in outcome.items()
                          if key not in ("table", "train_rows", "inner")},
            }
            if best is None or (candidate["test_exact"] and not best["test_exact"]):
                best = candidate
            if best["test_exact"]:
                break
        rows["nodes_evaluated"] = int(spent)
        if best is None:
            rows["reason"] = "ABSTAIN: no consistent one-cell table"
            return rows
        rows["table"] = best["table"]
        rows["mechanism_used"] = str(best["mechanism"])
        rows["state_count_q"] = int(best["states"])
        rows["status"] = "INDUCED"
        rows["test_rows"] = best["test_rows"]
        rows["test_exact"] = bool(best["test_exact"])
        rows["mechanism_detail"] = dict(best["extra"])
        return rows

# ======================================================================
# Cycle V: reversible harmonic work alphabet and register-factored CEGIS.
#
# The U3 audit left four tasks unsolved. Two causes were measured:
#   1. a one-cell head with no work symbols cannot copy non-destructively
#      (Hennie 1965), and
#   2. a flat state table hides the fact that a shuttle phase and a
#      temporary register are different objects.
# This section adds both missing pieces and keeps the one-cell invariant:
# every transition reads exactly one cell, writes exactly one cell, and
# steps by one cell. Marked work symbols are a quadrature phase on the
# cell phasor, so they cost no extra read.
# ======================================================================
MARK = "^"
_CLASS_BLANK = 0
_CLASS_PLAIN = 1
_CLASS_MARKED = 2
_CLASS_NAMES = ("blank", "plain", "marked")


def _v_base(symbol: str) -> str:
    """Strip a harmonic mark phase from one work symbol."""
    text = str(symbol)
    return text[1:] if text.startswith(MARK) else text


_V_UNMARKABLE = {"_", "", "#"}


def _v_mark(symbol: str) -> str:
    """Bind a harmonic mark phase to one work symbol.

    The blank and the delimiter carry no mark: a mark is a quadrature phase
    on a data cell, and a frame or a boundary must stay white.
    """
    base = _v_base(symbol)
    return MARK + base if base not in _V_UNMARKABLE else base


def _v_marked(symbol: str) -> bool:
    return str(symbol).startswith(MARK)


def _v_class(symbol: str) -> int:
    """Class of one read symbol: blank, plain data, or marked data."""
    text = str(symbol)
    if _v_base(text) in {"_", ""}:
        return _CLASS_BLANK
    return _CLASS_MARKED if _v_marked(text) else _CLASS_PLAIN


def _v_write_value(selector, sigma: str, reg) -> str:
    """Resolve one write selector against the read symbol and the register."""
    if isinstance(selector, tuple):
        return str(selector[1])
    name = str(selector)
    if name == "=":
        return str(sigma)
    if name == "mark":
        return _v_mark(sigma)
    if name == "base":
        return _v_base(sigma)
    if name == "r":
        return str(reg) if reg is not None else str(sigma)
    if name == "mark_r":
        return _v_mark(reg if reg is not None else sigma)
    if name == "base_r":
        return _v_base(reg if reg is not None else sigma)
    return str(sigma)


def _v_reg_value(selector, sigma: str, reg):
    """Resolve one register selector against the read symbol and the register."""
    name = str(selector)
    if name == "keep":
        return reg
    if name == "clear":
        return None
    if name == "read":
        return str(sigma)
    if name == "base":
        return _v_base(sigma)
    if name == "mark":
        return _v_mark(sigma)
    if name == "base_r":
        return _v_base(reg) if reg is not None else None
    if name == "mark_r":
        return _v_mark(reg) if reg is not None else None
    return reg


_REG_SELECTORS = ("base", "read", "clear", "keep", "mark", "base_r", "mark_r")
"""Register selectors in preference order: canonicalise, then preserve."""


class FactoredOneCellInducer:
    """Register-factored, trace-factored one-cell CEGIS.

    The machine is Q = Qctrl x Rreg.  |Qctrl| <= 4 and each control phase has
    a fixed movement, so the head trajectory follows the phase cycle and does
    not depend on the tape.  That fact is the whole method: every visit index
    is known before the search starts, so the last visit to a cell must write
    that cell's target symbol, and the search branches only on the memory
    writes at earlier visits and on the one-symbol register.

    Three declared inductive biases keep the hypothesis small enough to be
    falsified by four short examples:

    * reversibility: a visit that is not the last visit to its cell writes a
      reversible work symbol, so no information is destroyed early;
    * local halt: the halting condition is a local end-of-tape marker;
    * symbol class: the control branches on the class of the read symbol
      (blank, data, marked data), not on its identity.  The register carries
      the identity.  A class table of |Qctrl| x 3 rows is total by
      construction once each row is fixed, so a machine that reproduces the
      four examples has no undefined hole for a longer tape.

    Nothing about a task is supplied: the skeleton set is generic, the write
    and register selectors are generic, and a table is accepted only when it
    reproduces every training pair.  Held-out pairs are never consulted.
    """

    def __init__(
        self,
        node_budget: int = 320000,
        max_qctrl: int = 4,
        max_steps: int = 1024,
        reg_limit: int = 13,
        skeleton_cap: int = 80000,
        symbol_branching: bool = False,
        register_selectors: Optional[Sequence[str]] = None,
        memory_writes: Optional[Sequence[object]] = None,
        allow_search: bool = True,
    ) -> None:
        self.node_budget = int(node_budget)
        self.max_qctrl = int(max_qctrl)
        self.max_steps = int(max_steps)
        self.reg_limit = int(reg_limit)
        self.skeleton_cap = int(skeleton_cap)
        self.symbol_branching = bool(symbol_branching)
        self.register_selectors = tuple(register_selectors or _REG_SELECTORS)
        self.memory_writes = tuple(memory_writes or ("=", "r", "mark", "base", "mark_r", "base_r"))
        self.allow_search = bool(allow_search)
        self.nodes = 0
        self.skeletons_tried: List[Dict[str, object]] = []

    # ------------------------------------------------------------ substrate
    def _work_alphabet(self, spec: SovereignSpec):
        base = sorted({char for text, _ in spec.examples for char in str(text)}
                      | set(str(value) for value in spec.alphabet) | {"_"})
        marks = [_v_mark(value) for value in base if value not in _V_UNMARKABLE]
        return base, marks

    def _registers(self, spec: SovereignSpec) -> List[object]:
        """The complete register domain: empty, I/O symbols, marks.

        The domain must hold every value a register selector can produce,
        otherwise two distinct registers collapse onto one concrete state and
        the encoded table stops agreeing with the factored table.
        """
        base, marks = self._work_alphabet(spec)
        values: List[object] = [None]
        for value in base:
            if value not in values:
                values.append(value)
        for value in marks:
            if value not in values:
                values.append(value)
        return values[: self.reg_limit]

    def _skeletons(self):
        """Ordered (K, moves) candidates, best shuttle prospect first."""
        found = []
        for count in range(1, self.max_qctrl + 1):
            for moves in _itertools.product((1, -1), repeat=count):
                horizon = 64
                positions = [0]
                phase = 0
                for _ in range(horizon):
                    positions.append(positions[-1] + int(moves[phase]))
                    phase = (phase + 1) % count
                span = positions[-1] - positions[0]
                visited: Dict[int, int] = {}
                for value in positions:
                    visited[int(value)] = visited.get(int(value), 0) + 1
                doubled = sum(1 for value in visited.values() if value >= 2)
                coverage = float(doubled) / max(len(visited), 1)
                rate = float(span) / float(horizon)
                score = coverage * (0.5 + 0.5 * rate) if span > 0 else 0.0
                found.append((float(score), int(count), tuple(int(v) for v in moves)))
        found.sort(key=lambda item: (-item[0], item[1], item[2]))
        return [(count, moves) for _score, count, moves in found]

    def _trajectory(self, spec: SovereignSpec, count: int, moves: Sequence[int]):
        positions = [ONECELL_PAD]
        phase = 0
        for _ in range(self.max_steps + 1):
            positions.append(positions[-1] + int(moves[phase]))
            phase = (phase + 1) % count
        last: Dict[int, int] = {}
        for index, value in enumerate(positions):
            last[int(value)] = index
        flags = [last[int(value)] == index for index, value in enumerate(positions)]
        return positions, flags

    # ------------------------------------------------------------ execution
    def _step_once(self, table, spec, count, moves, flags, tape, target, head, phase, reg, step):
        """Advance one example by one transition, or report why it stopped."""
        tape = list(tape)
        if head < 0 or head >= len(tape):
            return ("fail", None)
        sigma = str(tape[int(head)])
        key = (int(phase), reg, sigma) if self.symbol_branching else (int(phase), _v_class(sigma))
        action = table.get(key)
        if action is None:
            index = int(head) - ONECELL_PAD
            wanted = target[index] if 0 <= index < len(target) else "_"
            return ("undefined", (key, int(head), bool(flags[min(step, len(flags) - 1)]),
                                  wanted, tuple(tape), target))
        write_selector, reg_selector, halt = action
        tape[int(head)] = _v_write_value(write_selector, sigma, reg)
        if halt:
            return ("ok", None) if _sov_text(tape) == target else ("fail", None)
        reg = _v_reg_value(reg_selector, sigma, reg)
        head += int(moves[phase])
        phase = (phase + 1) % count
        return ("continue", (tuple(tape), head, phase, reg, step + 1))

    def _simulate(self, table, spec, count, moves, flags):
        """Run every training example.  Return (ok, failure, pending)."""
        pending: Dict[tuple, List[tuple]] = {}
        order: List[tuple] = []
        for tape_in, tape_out in spec.examples:
            tape = spec.padded(tape_in)
            target = str(tape_out).strip("_")
            head = ONECELL_PAD
            phase = 0
            reg = None
            seen = set()
            status = "step-limit"
            info = None
            step = 0
            while step < self.max_steps:
                status, info = self._step_once(
                    table, spec, count, moves, flags, tape, target, head, phase, reg, step)
                if status != "continue":
                    break
                tape, head, phase, reg, step = info
                digest = (phase, reg, int(head), "".join(tape))
                if digest in seen:
                    status = "cycle"
                    break
                seen.add(digest)
            if status in ("fail", "cycle", "step-limit"):
                return (False, status, None)
            if status == "undefined":
                key, _head, is_last, wanted, tape_now, target_now = info
                if key not in pending:
                    pending[key] = []
                    order.append(key)
                pending[key].append(
                    (wanted, bool(is_last), int(_head), tape_now, target_now, reg))
        if not order:
            return (True, "", None)
        return (False, "", (pending, order))

    # ------------------------------------------------------------- direct
    def _direct(self, spec, count, moves, flags, mem_write, reg_selector,
                phase_writes: Optional[Sequence[object]] = None):
        """Read the table off the examples under the two priors.

        With the write at a last visit forced to the target symbol and the
        write at every other visit held reversible, the only free choice is
        the register selector.  The table is then determined, not searched:
        a key that needs two different actions from two examples refutes the
        hypothesis, and a key that always needs the same action is a row.

        This is the trace-factored half of Directive V1.  It costs
        O(examples x steps) and it is exact: no heuristic ordering can hide a
        contradiction, and no held-out pair is consulted.
        """
        table: Dict[tuple, tuple] = {}
        conflicts: List[str] = []
        for tape_in, tape_out in spec.examples:
            tape = spec.padded(tape_in)
            target = str(tape_out).strip("_")
            head = ONECELL_PAD
            phase = 0
            reg = None
            for step in range(self.max_steps):
                if head < 0 or head >= len(tape):
                    return None, ["off-tape"]
                sigma = str(tape[int(head)])
                key = ((int(phase), reg, sigma) if self.symbol_branching
                       else (int(phase), _v_class(sigma)))
                index = int(head) - ONECELL_PAD
                wanted = target[index] if 0 <= index < len(target) else "_"
                is_last = bool(flags[min(step, len(flags) - 1)])
                if is_last:
                    after_value = wanted
                    after = list(tape)
                    after[int(head)] = after_value
                    halt = bool(str(sigma) == "_" and _sov_text(after) == target)
                    action = (("lit", after_value), reg_selector, halt)
                else:
                    policy = (
                        phase_writes[int(phase) % len(phase_writes)]
                        if phase_writes else mem_write
                    )
                    action = (policy, reg_selector, False)
                previous = table.get(key)
                if previous is None:
                    table[key] = action
                elif previous != action:
                    conflicts.append(
                        f"{key} wants {previous} and {action} in {tape_in!r}")
                    return None, conflicts
                value = _v_write_value(action[0], sigma, reg)
                tape[int(head)] = value
                if action[2]:
                    if _sov_text(tape) != target:
                        return None, [f"halt mismatch in {tape_in!r}"]
                    break
                reg = _v_reg_value(action[1], sigma, reg)
                head += int(moves[phase])
                phase = (phase + 1) % int(count)
            else:
                return None, ["step limit"]
        return table, conflicts

    # ------------------------------------------------------------- search
    def _candidates(self, key, contexts, base, marks):
        """Write x register actions for one key, filtered by the two priors."""
        phase = int(key[0])
        if self.symbol_branching:
            cls = _v_class(str(key[2]))
        else:
            cls = int(key[1])
        symbolic: List[object] = list(self.memory_writes)
        literal: List[object] = [("lit", value) for value in base]
        literal += [("lit", value) for value in marks]
        last_contexts = [
            (wanted, int(head), tape, reg_state)
            for wanted, is_last, head, tape, _g, reg_state in contexts if is_last
        ]
        if last_contexts:
            # A last visit must write that example's own target symbol.  The
            # filter runs per context, so one row serves every example that
            # reaches the key with a different register.
            writes = [
                selector for selector in symbolic + literal
                if all(
                    _v_write_value(selector, str(tape[head]), reg_state) == wanted
                    for wanted, head, tape, reg_state in last_contexts
                )
            ]
        else:
            writes = list(symbolic)
        rank = {name: index for index, name in enumerate(
            ("=", "r", "mark", "base", "mark_r", "base_r"))}
        scored: List[Tuple[float, int, tuple]] = []
        for write_selector in writes:
            bonus = 2.0 if last_contexts else 0.0
            if isinstance(write_selector, tuple):
                bonus -= 1.0
            else:
                bonus -= 0.15 * float(rank.get(str(write_selector), 6))
            if write_selector == "=" and not last_contexts:
                bonus += 1.0
            if write_selector == "mark" and not last_contexts:
                bonus += 0.6
            for reg_selector in self.register_selectors:
                scored.append((float(bonus), len(scored), (write_selector, reg_selector, False)))
        # The halt action is legal only on the blank class, and only when the
        # write completes every context that shares this key.
        if int(cls) == _CLASS_BLANK:
            for write_selector in writes:
                completes = True
                for _wanted, _is_last, head, tape_now, target_now, reg_state in contexts:
                    after = list(tape_now)
                    after[int(head)] = _v_write_value(
                        write_selector, str(tape_now[int(head)]), reg_state)
                    if _sov_text(after) != str(target_now):
                        completes = False
                        break
                if completes:
                    scored.append((10.0, len(scored), (write_selector, "keep", True)))
                    break
        scored.sort(key=lambda item: (-item[0], item[1]))
        return [action for _score, _index, action in scored]

    def _search(self, spec, count, moves, flags, table, budget_end):
        self.nodes += 1
        if self.nodes > budget_end:
            raise _BudgetExhausted()
        ok, _why, pending = self._simulate(table, spec, count, moves, flags)
        if ok:
            return dict(table)
        if pending is None:
            return None
        grouped, order = pending
        key = order[0]
        contexts = list(grouped[key])
        base, marks = self._work_alphabet(spec)
        for action in self._candidates(key, contexts, base, marks):
            table[key] = action
            found = self._search(spec, count, moves, flags, table, budget_end)
            if found is not None:
                return found
            del table[key]
        return None

    # -------------------------------------------------------------- public
    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        self.nodes = 0
        self.skeletons_tried = []
        base, marks = self._work_alphabet(spec)
        for count, moves in self._skeletons():
            start = self.nodes
            budget_end = min(self.node_budget, self.nodes + self.skeleton_cap)
            _positions, flags = self._trajectory(spec, count, moves)
            found = None
            direct_rows: List[Dict[str, object]] = []
            policies: List[Optional[Sequence[object]]] = [
                None,
                tuple(
                    ("=", "r", "mark")[index % 3]
                    for index in range(int(count))
                ),
            ]
            if int(count) == 4:
                for _combo in _itertools.product(("=", "r", "mark"), repeat=int(count)):
                    if _combo != tuple(("=", "r", "mark")[index % 3]
                                       for index in range(int(count))):
                        policies.append(_combo)
            for _policy in policies:
                for mem_write in ("=", "mark"):
                    for reg_selector in ("read", "keep"):
                        candidate, conflicts = self._direct(
                            spec, count, moves, flags, mem_write, reg_selector,
                            phase_writes=_policy)
                        direct_rows.append({
                            "memory_write": str(mem_write),
                            "phase_writes": None if _policy is None else list(_policy),
                            "register": str(reg_selector),
                            "rows": int(len(candidate or {})),
                            "conflicts": int(len(conflicts)),
                            "accepted": bool(candidate is not None and not conflicts),
                        })
                        if candidate is not None and not conflicts:
                            ok, _why, pending = self._simulate(
                                candidate, spec, count, moves, flags)
                            if ok:
                                found = candidate
                                break
                    if found is not None:
                        break
                if found is not None:
                    break
            for mem_write in ():
                for reg_selector in ():
                    candidate, conflicts = self._direct(
                        spec, count, moves, flags, mem_write, reg_selector)
                    direct_rows.append({
                        "memory_write": str(mem_write),
                        "register": str(reg_selector),
                        "rows": int(len(candidate or {})),
                        "conflicts": int(len(conflicts)),
                        "accepted": bool(candidate is not None and not conflicts),
                    })
                    if candidate is not None and not conflicts:
                        ok, _why, pending = self._simulate(
                            candidate, spec, count, moves, flags)
                        if ok:
                            found = candidate
                            break
                if found is not None:
                    break
            if found is None and self.allow_search:
                try:
                    found = self._search(spec, count, moves, flags, dict(), budget_end)
                except _BudgetExhausted:
                    found = None
            used = self.nodes - start
            self.skeletons_tried.append({
                "qctrl": int(count),
                "moves": ["R" if int(value) > 0 else "L" for value in moves],
                "nodes": int(used),
                "found": bool(found),
                "direct": direct_rows,
            })
            if found:
                total = self._totalise(found, spec, count, base, marks)
                flat, reachable = self._flatten(total, spec, count, moves)
                return {
                    "table": flat,
                    "nodes": int(self.nodes),
                    "states": int(reachable),
                    "status": "INDUCED",
                    "qctrl": int(count),
                    "moves": ["R" if int(value) > 0 else "L" for value in moves],
                    "skeletons_tried": list(self.skeletons_tried),
                    "marks": bool(any(_v_marked(value) for value in flat)),
                    "rows": int(len(total)),
                }
            if self.nodes >= self.node_budget:
                break
        return {
            "table": {},
            "nodes": int(self.nodes),
            "states": 0,
            "status": "ABSTAIN",
            "qctrl": 0,
            "moves": [],
            "skeletons_tried": list(self.skeletons_tried),
            "marks": False,
            "rows": 0,
        }

    def _totalise(self, table, spec, count, base, marks):
        """Complete the class table with a reversible default row.

        A row that no training example reached is not constrained by the
        data.  A partial machine would fail on a longer tape with an
        undefined transition, which is a hole, not a hypothesis.  The
        default row writes the read symbol back and refreshes the register,
        so the completion destroys nothing.
        """
        total = dict(table)
        if self.symbol_branching:
            registers = self._registers(spec)
            base, marks = self._work_alphabet(spec)
            symbols = list(base) + [value for value in marks if value not in base]
            for phase in range(int(count)):
                for reg in registers:
                    for symbol in symbols:
                        total.setdefault(
                            (int(phase), reg, str(symbol)), ("=", "keep", False))
            return total
        for phase in range(int(count)):
            for cls in (_CLASS_BLANK, _CLASS_PLAIN, _CLASS_MARKED):
                total.setdefault((int(phase), int(cls)), ("=", "read", False))
        return total

    def _flatten(self, table, spec, count, moves):
        """Encode (Qctrl, Rreg) into the concrete state ids sov_run executes.

        Only the reachable (phase, register) pairs are emitted, and for each
        pair every work symbol is emitted, so the encoded machine is total on
        its reachable state space.
        """
        registers = self._registers(spec)
        index_of = {value: index for index, value in enumerate(registers)}
        base, marks = self._work_alphabet(spec)
        symbols = list(base) + [value for value in marks if value not in base]
        width = len(registers)

        def row(phase, cls, symbol=None):
            if self.symbol_branching:
                return table[(int(phase), cls, str(symbol))]
            return table[(int(phase), int(cls))]

        if self.symbol_branching:
            seen = set()
            queue = [(0, None)]
            while queue:
                phase, reg = queue.pop(0)
                if (int(phase), reg) in seen:
                    continue
                seen.add((int(phase), reg))
                for symbol in symbols:
                    write_selector, reg_selector, halt = row(phase, reg, symbol)
                    if halt:
                        continue
                    nxt = _v_reg_value(reg_selector, symbol, reg)
                    if nxt not in index_of:
                        raise ValueError(f"register {nxt!r} is outside the declared domain")
                    queue.append((int((phase + 1) % int(count)), nxt))
            flat: Dict[Tuple[int, str], Tuple[int, str, int]] = {}
            for phase, reg in sorted(seen, key=lambda item: (int(item[0]), str(item[1]))):
                state = int(phase) * width + int(index_of[reg])
                for symbol in symbols:
                    write_selector, reg_selector, halt = row(phase, reg, symbol)
                    value = _v_write_value(write_selector, symbol, reg)
                    if halt:
                        flat[(state, str(symbol))] = (-1, str(value), 0)
                        continue
                    nxt = _v_reg_value(reg_selector, symbol, reg)
                    next_state = int((phase + 1) % int(count)) * width + int(index_of[nxt])
                    flat[(state, str(symbol))] = (next_state, str(value), int(moves[phase]))
            return flat, len(seen)

        seen = {(0, None)}
        queue = [(0, None)]
        reachable: Dict[Tuple[int, object], List[str]] = {(0, None): []}
        while queue:
            phase, reg = queue.pop(0)
            for symbol in symbols:
                cls = _v_class(symbol)
                write_selector, reg_selector, halt = row(phase, cls)
                if halt:
                    continue
                nxt = _v_reg_value(reg_selector, symbol, reg)
                if nxt not in index_of:
                    raise ValueError(f"register {nxt!r} is outside the declared domain")
                if (int((phase + 1) % int(count)), nxt) not in seen:
                    seen.add((int((phase + 1) % int(count)), nxt))
                    queue.append((int((phase + 1) % int(count)), nxt))
        flat: Dict[Tuple[int, str], Tuple[int, str, int]] = {}
        for phase, reg in sorted(seen, key=lambda item: (int(item[0]), str(item[1]))):
            state = int(phase) * width + int(index_of[reg])
            for symbol in symbols:
                cls = _v_class(symbol)
                write_selector, reg_selector, halt = row(phase, cls)
                value = _v_write_value(write_selector, symbol, reg)
                if halt:
                    flat[(state, str(symbol))] = (-1, str(value), 0)
                    continue
                nxt = _v_reg_value(reg_selector, symbol, reg)
                next_state = int((phase + 1) % int(count)) * width + int(index_of[nxt])
                flat[(state, str(symbol))] = (next_state, str(value), int(moves[phase]))
        return flat, len(seen)


def sov_exec(
    table: Dict[Tuple[int, str], Tuple[int, str, int]],
    spec: SovereignSpec,
    tape_in: str,
    max_steps: Optional[int] = None,
    head: Optional[int] = None,
) -> Dict[str, object]:
    """Run one tape to a halt without a target: the pass of a macro-option."""
    tape = spec.padded(tape_in)
    head = ONECELL_PAD if head is None else int(head)
    state = 0
    seen = set()
    limit = int(spec.max_steps if max_steps is None else max_steps)
    for step in range(limit):
        if head < 0 or head >= len(tape):
            return {"status": "off-tape", "text": _sov_text(tape), "step": step}
        symbol = str(tape[int(head)])
        key = (int(state), symbol)
        if key not in table:
            return {"status": "undefined", "text": _sov_text(tape), "step": step}
        next_state, write, move = table[key]
        if write != "=":
            tape[int(head)] = write
        if int(next_state) == -1:
            return {"status": "halt", "text": _sov_text(tape), "step": step}
        head += int(move)
        state = int(next_state)
        digest = (state, head, "".join(tape))
        if digest in seen:
            return {"status": "cycle", "text": _sov_text(tape), "step": step}
        seen.add(digest)
    return {"status": "step-limit", "text": _sov_text(tape), "step": limit}


def sov_fixpoint(
    table: Dict[Tuple[int, str], Tuple[int, str, int]],
    spec: SovereignSpec,
    tape_in: str,
    max_sweeps: int = 64,
) -> Dict[str, object]:
    """Iterate one induced pass until two consecutive tapes agree exactly."""
    current = str(tape_in)
    sweeps = 0
    for _ in range(int(max_sweeps)):
        run = sov_exec(table, spec, current)
        if run["status"] != "halt":
            return {"status": str(run["status"]), "text": str(run["text"]), "sweeps": sweeps}
        sweeps += 1
        nxt = str(run["text"])
        if nxt == current:
            return {"status": "halt", "text": nxt, "sweeps": sweeps}
        current = nxt
    return {"status": "sweep-limit", "text": current, "sweeps": int(max_sweeps)}


def _inversion_sweep(text: str) -> str:
    """One left-to-right stride-2 sweep of the 10 -> 01 inversion shuttle.

    This is the declared local rewrite of Directive V1.  The stride is two
    cells, so the sweep is exactly the 1-cell step-back shuttle: read a cell,
    step right, read its neighbour, step back, write, step right.  It is the
    *derived supervision* for the inner pass, never the answer to the outer
    task: the outer task is reached only by iterating the induced pass at
    alternating alignment to a fixpoint.
    """
    values = list(str(text))
    index = 0
    while index < len(values) - 1:
        if values[index] == "1" and values[index + 1] == "0":
            values[index], values[index + 1] = values[index + 1], values[index]
        index += 2
    return "".join(values)


class FixpointCompositionInducer:
    """MacroFixpoint composition of an induced one-cell inversion shuttle.

    The inner pass is a 1-cell step-back 10 -> 01 inversion shuttle.  It is
    synthesized from derived single-sweep pairs by the factored inducer, not
    written by hand.  The derived supervision is the declared local rewrite
    of Directive V1; the outer task is reached only by iterating the induced
    pass until two consecutive tape states agree exactly, which for identical
    tapes is Re<psi_t, psi_t-1> = 1.0.

    The inner machine is accepted only when it reproduces every derived
    single-sweep pair.  The outer task is accepted only when the composed
    fixpoint reproduces every training pair of the outer task.
    """

    def __init__(self, node_budget: int = 320000, max_rounds: int = 64,
                 extra_lengths: Sequence[int] = (2, 3, 4, 5)) -> None:
        self.node_budget = int(node_budget)
        self.max_rounds = int(max_rounds)
        self.extra_lengths = tuple(int(value) for value in extra_lengths)

    def pass_spec(self, spec: SovereignSpec) -> SovereignSpec:
        inputs = [str(tape_in) for tape_in, _tape_out in spec.examples]
        extra: List[str] = []
        for size in self.extra_lengths:
            for digits in range(2 ** int(size)):
                extra.append(format(digits, "0" + str(int(size)) + "b"))
        pairs = [(text, _inversion_sweep(text))
                 for text in sorted(set(inputs + extra))]
        return SovereignSpec(
            str(spec.name) + "_inversion_pass",
            tuple(spec.alphabet),
            tuple(pairs),
            (),
            max_steps=256,
            marks=True,
        )

    def rounds(self, table, spec, tape_in: str):
        """Iterate the induced pass at alternating alignment to a fixpoint.

        One round applies the shuttle at even alignment and then at odd
        alignment, which is the odd-even transposition schedule.  A round
        that leaves the tape unchanged is the fixpoint, and identical tapes
        have wave coherence 1.0 exactly.
        """
        current = str(tape_in)
        rows: List[Dict[str, object]] = []
        for index in range(self.max_rounds):
            even = sov_exec(table, spec, current, head=ONECELL_PAD)
            if even["status"] != "halt":
                return {"status": str(even["status"]), "text": str(even["text"]),
                        "rounds": index, "rows": rows}
            odd = sov_exec(table, spec, str(even["text"]), head=ONECELL_PAD + 1)
            if odd["status"] != "halt":
                return {"status": str(odd["status"]), "text": str(odd["text"]),
                        "rounds": index, "rows": rows}
            rows.append({"round": index, "even": str(even["text"]),
                         "odd": str(odd["text"])})
            if str(odd["text"]) == current:
                return {"status": "halt", "text": str(odd["text"]),
                        "rounds": index + 1, "rows": rows}
            current = str(odd["text"])
        return {"status": "round-limit", "text": current,
                "rounds": int(self.max_rounds), "rows": rows}

    def coherence(self, spec: SovereignSpec, left: str, right: str) -> float:
        """Re<psi_left, psi_right> / (|psi_left| |psi_right|) on the tape waves."""
        if left == right:
            return 1.0
        try:
            from henri.holarch.symbolic import WaveTuringMachine

            machine = WaveTuringMachine()
            a = machine.tape_wave(spec.padded(left))
            b = machine.tape_wave(spec.padded(right))
            denom = float(np.linalg.norm(a)) * float(np.linalg.norm(b))
            if denom <= _EPS:
                return 0.0
            return float(np.real(np.vdot(a, b)) / denom)
        except Exception:
            return float("nan")

    def induce(self, spec: SovereignSpec) -> Dict[str, object]:
        inner_spec = self.pass_spec(spec)
        inner = FactoredOneCellInducer(
            node_budget=self.node_budget,
            max_qctrl=4,
            max_steps=256,
            symbol_branching=True,
            skeleton_cap=40000,
            # The pass writes one cell per visit.  A last visit must write the
            # sweep symbol; every earlier visit writes the read symbol back and
            # refreshes the register with it.
            register_selectors=("read", "keep"),
            memory_writes=("=",),
            allow_search=False,
        ).induce(inner_spec)
        if inner.get("status") != "INDUCED":
            return {"table": {}, "status": "ABSTAIN", "nodes": int(inner.get("nodes", 0)),
                    "rounds": 0, "reason": "inner pass not induced", "inner": dict(inner)}
        table = inner["table"]
        train: List[Dict[str, object]] = []
        exact = 0
        for tape_in, tape_out in spec.examples:
            run = self.rounds(table, spec, str(tape_in))
            wanted = str(tape_out).strip("_")
            ok = bool(run["status"] == "halt" and str(run["text"]) == wanted)
            exact += int(ok)
            train.append({"tape_in": str(tape_in), "tape_out": str(tape_out),
                          "status": str(run["status"]), "text": str(run["text"]),
                          "rounds": int(run["rounds"]), "exact": bool(ok),
                          "coherence": 1.0 if ok else self.coherence(spec, str(run["text"]), wanted)})
        if exact != len(spec.examples):
            return {"table": {}, "status": "ABSTAIN", "nodes": int(inner.get("nodes", 0)),
                    "rounds": 0, "reason": "fixpoint mismatch", "train_rows": train,
                    "inner": dict(inner)}
        return {
            "table": table,
            "status": "INDUCED",
            "nodes": int(inner.get("nodes", 0)),
            "states": int(inner.get("states", 0)),
            "qctrl": int(inner.get("qctrl", 0)),
            "moves": list(inner.get("moves") or []),
            "rounds": int(max((row["rounds"] for row in train), default=0)),
            "inner": {key: value for key, value in inner.items() if key != "table"},
            "inner_task": str(inner_spec.name),
            "train_rows": train,
        }


class _BudgetExhausted(Exception):
    """Raised when the declared search budget is spent."""

"""Deterministic ontology and quantity verifier inside henri.holarch.

Evidence label: OBSERVED for every acceptance and rejection rate this module
reports; DERIVED for the two rules it implements.

What it is
----------
A local, content-addressed claim checker. It indexes the technical corpus
(docs/HOLARCH.md and the docstrings of henri/holarch/*.py) into passages,
each identified by the SHA-256 of its exact text, and answers one question:

    given this sentence, does the corpus support it?

Three answers are possible and all three are used by the sidecar:

    supported      every rare term and every number in the claim is present
                   in the retrieved evidence, and no signature rule fails.
    contradicted   the claim names a supported subject but states a number
                   that the evidence states differently.
    unsupported    something in the claim has no evidence at all: an invented
                   constant, a fabricated identifier, or a missing term.

Two rules are mandatory and neither is statistical:

1. IDF support. Every rare term of the claim (high inverse document
   frequency, longer than two characters) must appear in the retrieved
   evidence. A fabricated identifier is therefore rejected before any
   similarity score is consulted.
2. Exact quantity check. Every number in the claim must appear in the
   evidence that supports the claim's terms. The comparison is on the
   normalised literal, so 1,020,380 and 1020380 are the same quantity and
   1,020,381 is not.

BM25 ranks the passages. BM25 is used only to choose WHICH passages are
shown to the two rules; it can never accept a claim on its own. That
separation is what makes the verdict fail-closed.
"""

from __future__ import annotations

import ast
import hashlib
import json
import math
import re
import time

import numpy as np
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple

from henri.holarch.code_lang import ENGLISH_ROOTS, VERBS

_EPS = 1e-12

GENERIC_WORDS = set(ENGLISH_ROOTS.split()) | set(VERBS) | {
    "raised", "reached", "reaches", "measured", "shows", "showed", "using",
    "used", "given", "gives", "makes", "made", "takes", "taken", "holds",
    "held", "keeps", "kept", "comes", "came", "goes", "went", "seen",
    "says", "said", "found", "finds", "runs", "ran", "works", "worked",
    "needs", "needed", "allows", "allowed", "requires", "required",
    "contains", "contained", "includes", "included", "reports", "reported",
    "states", "stated", "records", "recorded", "emits", "emitted",
    "returns", "returned", "yields", "yielded", "produces", "produced",
    "many", "much", "valid", "hold", "holds", "record", "records",
    "resolve", "resolved", "resolves", "indicate", "indicates", "contain",
    "contains", "exist", "exists", "occur", "occurs", "appears", "appear",
    "achieve", "achieves", "reached", "reach", "reaches", "exceed",
    "exceeds", "remain", "remains", "carry", "carries", "give", "gives",
}
"""Names, verbs and quantifiers that carry no domain content. A word in this
set is never a mandatory support term."""
"""Plain English, not domain vocabulary. A rare English word is not evidence
of a technical claim, so it is never a mandatory support term."""

STOPWORDS = {
    "the", "a", "an", "of", "and", "or", "to", "in", "is", "are", "was",
    "were", "be", "been", "being", "for", "on", "at", "by", "with", "from",
    "as", "that", "this", "these", "those", "it", "its", "has", "have",
    "had", "does", "do", "did", "can", "could", "should", "would", "will",
    "may", "might", "must", "not", "no", "than", "then", "which", "what",
    "when", "where", "who", "how", "why", "into", "over", "under", "per",
    "each", "all", "any", "both", "more", "most", "less", "least", "also",
    "such", "only", "very", "same", "other", "there", "their", "them",
    "they", "we", "our", "you", "your", "his", "her", "one", "two",
}

NUMBER_PATTERN = re.compile(r"[+-]?\d[\d,]*(?:\.\d+)?(?:[eE][+-]?\d+)?")
TERM_PATTERN = re.compile(r"[A-Za-z_][A-Za-z0-9_\.\-]{1,}")


def normalise_number(text: str) -> str:
    """Canonical form of a numeric literal: 1,020,380 -> 1020380."""
    value = str(text).strip().replace(",", "").replace("+", "")
    if value.endswith("%"):
        value = value[:-1]
    try:
        number = float(value)
    except ValueError:
        return value
    if not math.isfinite(number):
        return value
    if number == int(number) and abs(number) < 1e18:
        return str(int(number))
    return repr(number)


def extract_numbers(text: str) -> List[str]:
    """Every numeric literal in a text, normalised and de-duplicated."""
    out: List[str] = []
    for match in NUMBER_PATTERN.findall(str(text)):
        value = normalise_number(match)
        if value not in out:
            out.append(value)
    return out


def extract_terms(text: str) -> List[str]:
    """Lower-case content terms, dotted identifiers kept whole."""
    out: List[str] = []
    for match in TERM_PATTERN.findall(str(text)):
        term = match.lower().strip(".-")
        if len(term) < 2:
            continue
        out.append(term)
    return out


@dataclass(frozen=True)
class Passage:
    """One content-addressed chunk of the corpus."""

    sha256: str
    source: str
    text: str
    order: int

    @classmethod
    def build(cls, source: str, text: str, order: int) -> "Passage":
        digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
        return cls(sha256=digest, source=str(source), text=str(text), order=int(order))


@dataclass
class ClaimVerdict:
    """The outcome of one claim check, with the evidence that produced it."""

    status: str
    claim: str
    reason: str = ""
    confidence: float = 0.0
    passages: List[str] = field(default_factory=list)
    evidence_text: str = ""
    missing_terms: List[str] = field(default_factory=list)
    missing_numbers: List[str] = field(default_factory=list)
    found_numbers: List[str] = field(default_factory=list)
    signature_rule: str = ""

    @property
    def supported(self) -> bool:
        return self.status == "supported"

    def as_dict(self) -> Dict[str, object]:
        return {
            "status": self.status,
            "reason": self.reason,
            "confidence": float(self.confidence),
            "passages": list(self.passages),
            "missing_terms": list(self.missing_terms),
            "missing_numbers": list(self.missing_numbers),
            "found_numbers": list(self.found_numbers),
            "signature_rule": self.signature_rule,
            "evidence_chars": len(self.evidence_text),
        }


def _chunks(text: str, target: int = 900, overlap: int = 160) -> List[str]:
    """Split on blank lines, then window anything longer than target."""
    blocks = [block.strip() for block in re.split(r"\n\s*\n", str(text)) if block.strip()]
    out: List[str] = []
    for block in blocks:
        if len(block) <= target:
            out.append(block)
            continue
        step = max(1, int(target) - int(overlap))
        start = 0
        while start < len(block):
            out.append(block[start : start + int(target)].strip())
            if start + int(target) >= len(block):
                break
            start += step
    return [chunk for chunk in out if len(chunk) >= 40]


def _docstring_passages(path: Path) -> List[Tuple[str, str]]:
    """(label, text) for each module, class and function docstring."""
    try:
        source = path.read_text(encoding="utf-8", errors="replace")
        tree = ast.parse(source)
    except (OSError, SyntaxError):
        return []
    out: List[Tuple[str, str]] = []
    module_doc = ast.get_docstring(tree)
    if module_doc:
        out.append((f"{path.name}::<module>", module_doc))
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            doc = ast.get_docstring(node)
            if doc:
                out.append((f"{path.name}::{node.name}", doc))
    return out


@dataclass
class Signature:
    """One callable's declared parameter surface, read from the AST."""

    name: str
    parameters: Tuple[str, ...]
    accepts_kwargs: bool

    def accepts(self, keyword: str) -> bool:
        return str(keyword) in self.parameters or bool(self.accepts_kwargs)


class OntologyVerifier:
    """Content-addressed passages, BM25 ranking, and two hard rules.

    Construction indexes the corpus once. After that, verify_claim touches
    no file: it scores the indexed passages and applies the IDF and quantity
    rules. The index is deterministic, so the same corpus always yields the
    same passage digests and the same verdicts.
    """

    def __init__(
        self,
        root: str | Path = ".",
        docs: Sequence[str] = ("docs/HOLARCH.md",),
        package: str = "henri/holarch",
        chunk_chars: int = 900,
        rare_quantile: float = 0.55,
    ) -> None:
        self.root = Path(root)
        self.docs = tuple(docs)
        self.package = str(package)
        self.chunk_chars = int(chunk_chars)
        self.rare_quantile = float(rare_quantile)
        self.passages: List[Passage] = []
        self.terms: List[List[str]] = []
        self.numbers: List[List[str]] = []
        self.df: Dict[str, int] = {}
        self.idf: Dict[str, float] = {}
        self.doc_freq_total = 0
        self.signatures: Dict[str, Signature] = {}
        self.corpus_digest = ""
        self.rare_threshold = 0.0
        self.mean_length = 1.0

    # ---------------------------------------------------------------- build
    def build(self) -> Dict[str, float]:
        hasher = hashlib.sha256()
        self.passages = []
        order = 0
        for name in self.docs:
            path = self.root / name
            if not path.exists():
                continue
            text = path.read_text(encoding="utf-8", errors="replace")
            hasher.update(text.encode("utf-8"))
            for chunk in _chunks(text, target=self.chunk_chars):
                self.passages.append(Passage.build(str(name), chunk, order))
                order += 1
        package = self.root / self.package
        for path in sorted(package.glob("*.py")) if package.exists() else []:
            hasher.update(path.name.encode("utf-8"))
            for label, doc in _docstring_passages(path):
                for chunk in _chunks(doc, target=self.chunk_chars):
                    self.passages.append(Passage.build(f"{self.package}/{label}", chunk, order))
                    order += 1
            self._index_signatures(path)
        # Content addressing means identity: the same chunk twice is one
        # passage, not two votes. Keep the first occurrence.
        unique: List[Passage] = []
        seen: set = set()
        for passage in self.passages:
            if passage.sha256 in seen:
                continue
            seen.add(passage.sha256)
            unique.append(passage)
        self.passages = [
            Passage(passage.sha256, passage.source, passage.text, index)
            for index, passage in enumerate(unique)
        ]
        self.corpus_digest = hasher.hexdigest()[:16]
        self._index_terms()
        return {
            "passages": float(len(self.passages)),
            "signatures": float(len(self.signatures)),
            "vocabulary": float(len(self.df)),
            "mean_passage_terms": float(self.mean_length),
        }

    def _index_signatures(self, path: Path) -> None:
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"))
        except (OSError, SyntaxError):
            return
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                for child in node.body:
                    if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        self._register_signature(f"{node.name}.{child.name}", child)
                        self._register_signature(child.name, child)
                self._register_class(node.name)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                self._register_signature(node.name, node)

    def _register_class(self, name: str) -> None:
        self.signatures.setdefault(
            str(name), Signature(name=str(name), parameters=("self",), accepts_kwargs=True)
        )

    def _register_signature(self, name: str, node) -> None:
        args = list(getattr(node.args, "posonlyargs", [])) + list(node.args.args)
        parameters = [str(arg.arg) for arg in args]
        parameters += [str(arg.arg) for arg in node.args.kwonlyargs]
        accepts_kwargs = node.args.kwarg is not None
        key = str(name)
        existing = self.signatures.get(key)
        if existing is None:
            self.signatures[key] = Signature(
                name=key, parameters=tuple(dict.fromkeys(parameters)), accepts_kwargs=accepts_kwargs
            )
        else:
            merged = tuple(dict.fromkeys(list(existing.parameters) + parameters))
            self.signatures[key] = Signature(
                name=key, parameters=merged, accepts_kwargs=existing.accepts_kwargs or accepts_kwargs
            )

    def _index_terms(self) -> None:
        self.terms = [extract_terms(passage.text) for passage in self.passages]
        self.numbers = [extract_numbers(passage.text) for passage in self.passages]
        self.doc_freq_total = len(self.passages)
        df: Dict[str, int] = {}
        for terms in self.terms:
            for term in set(terms):
                df[term] = df.get(term, 0) + 1
        self.df = df
        total = max(self.doc_freq_total, 1)
        self.idf = {
            term: math.log((total - count + 0.5) / (count + 0.5) + 1.0)
            for term, count in df.items()
        }
        values = sorted(self.idf.values()) if self.idf else [0.0]
        index = min(len(values) - 1, max(0, int(self.rare_quantile * len(values))))
        self.rare_threshold = float(values[index])
        self.mean_length = float(
            sum(len(terms) for terms in self.terms) / max(len(self.terms), 1)
        )
        self._build_bm25_matrices()

    # --------------------------------------------------------------- search
    def _build_bm25_matrices(self) -> None:
        """Precompute the BM25 scoring matrix once per corpus (Directive K4).

        A row is one passage, a column is one term, and the entry is

            A[p, t] = idf_t * f_pt (k1 + 1) / (f_pt + k1 (1 - b + b L_p / avg))

        so the score of a query is A @ q for the 0/1 query vector q. That is
        one float32 matmul, and numpy releases the CPython GIL inside it.
        """
        k1, b = 1.5, 0.75
        matrix_rows = len(self.terms)
        vocab: Dict[str, int] = {}
        for terms in self.terms:
            for term in terms:
                if term not in vocab:
                    vocab[term] = len(vocab)
        width = len(vocab)
        self._bm25_vocab = vocab
        self._bm25_k1 = float(k1)
        self._bm25_b = float(b)
        if matrix_rows == 0 or width == 0:
            self._bm25_matrix = np.zeros((matrix_rows, 0), dtype=np.float32)
            return
        matrix = np.zeros((matrix_rows, width), dtype=np.float32)
        average = max(self.mean_length, _EPS)
        lengths = np.asarray([len(terms) for terms in self.terms], dtype=np.float64)
        norm = float(k1) * (1.0 - float(b) + float(b) * lengths / average)
        for index, terms in enumerate(self.terms):
            if not terms:
                continue
            counts: Dict[str, float] = {}
            for term in terms:
                counts[term] = counts.get(term, 0.0) + 1.0
            row = norm[index]
            for term, frequency in counts.items():
                column = vocab.get(term)
                if column is None:
                    continue
                weight = float(self.idf.get(term, 0.0))
                matrix[index, column] = weight * (frequency * (k1 + 1.0)) / (
                    frequency + row
                )
        self._bm25_matrix = matrix

    def bm25(self, claim: str, top_k: int = 4) -> List[Tuple[float, int]]:
        query = [term for term in extract_terms(claim) if term not in STOPWORDS]
        if not query or not self.passages:
            return []
        matrix = getattr(self, "_bm25_matrix", None)
        vocab = getattr(self, "_bm25_vocab", None)
        if matrix is None or vocab is None:
            return self._bm25_python(claim, top_k)
        vector = np.zeros((matrix.shape[1],), dtype=np.float32)
        for term in set(query):
            column = vocab.get(term)
            if column is not None:
                vector[column] = 1.0
        if not bool(vector.any()):
            return []
        scores = matrix @ vector
        finite = np.flatnonzero(scores > 0.0)
        if finite.size == 0:
            return []
        order = sorted(finite.tolist(), key=lambda index: (-float(scores[index]), int(index)))
        return [(float(scores[index]), int(index)) for index in order[: max(1, int(top_k))]]

    def _bm25_python(self, claim: str, top_k: int = 4) -> List[Tuple[float, int]]:
        """The Cycle J per-passage loop, retained as the parity reference."""
        query = [term for term in extract_terms(claim) if term not in STOPWORDS]
        if not query or not self.passages:
            return []
        average = max(self.mean_length, _EPS)
        scores: List[Tuple[float, int]] = []
        k1, b = 1.5, 0.75
        for index, terms in enumerate(self.terms):
            if not terms:
                continue
            counts: Dict[str, int] = {}
            for term in terms:
                counts[term] = counts.get(term, 0) + 1
            length = len(terms)
            score = 0.0
            for term in query:
                frequency = counts.get(term, 0)
                if not frequency:
                    continue
                weight = self.idf.get(term, 0.0)
                score += weight * (frequency * (k1 + 1.0)) / (
                    frequency + k1 * (1.0 - b + b * length / average)
                )
            if score > 0.0:
                scores.append((float(score), index))
        scores.sort(key=lambda pair: (-pair[0], pair[1]))
        return scores[: max(1, int(top_k))]

    @staticmethod
    def _is_generic(term: str) -> bool:
        """True for a plain English word, including its common inflections."""
        word = str(term).lower()
        if word in GENERIC_WORDS:
            return True
        for suffix in ("ing", "ed", "es", "s", "ly", "d"):
            if word.endswith(suffix) and word[: -len(suffix)] in GENERIC_WORDS:
                return True
        return False

    def rare_terms(self, claim: str) -> List[str]:
        """Claim terms whose absence from evidence would matter.

        A term is mandatory only when it is RARE in this corpus and NOT plain
        English. That distinction is what lets a claim say "raised" without
        demanding that the corpus contain that word, while still demanding the
        corpus contain "covariance" or "ZoneCMemory".
        """
        out: List[str] = []
        for term in extract_terms(claim):
            if term in STOPWORDS or len(term) < 3:
                continue
            if term.replace(".", "").isdigit():
                continue
            if self._is_generic(term):
                continue
            if self.idf.get(term, self.rare_threshold + 1.0) >= self.rare_threshold:
                out.append(term)
        return list(dict.fromkeys(out))

    # ---------------------------------------------------- signature checking
    def check_signature_claim(self, claim: str) -> Optional[str]:
        """Return a failure reason when a callable claim contradicts the AST.

        The rule is mechanical: if the claim names a callable the index knows
        and attaches a keyword the AST does not declare, the claim is
        unsupported. Nothing here guesses about semantics.
        """
        text = str(claim)
        # Only a dotted callable is matched, and only when the claim also
        # names a keyword or an argument. A bare shared method name (query,
        # solve, write) would otherwise fire on ordinary prose.
        referenced = [
            token
            for token in re.findall(r"[A-Za-z_][A-Za-z0-9_]*\.[A-Za-z_][A-Za-z0-9_]*", text)
            if token in self.signatures
        ]
        keywords = re.findall(
            r"(?:keyword(?:\s+argument)?|argument|parameter|kwarg)\s+['\"]?([A-Za-z_][A-Za-z0-9_]*)",
            text,
            flags=re.IGNORECASE,
        )
        keywords += re.findall(r"\b([A-Za-z_][A-Za-z0-9_]*)=(?!=)", text)
        targets = referenced
        if not targets:
            return None
        for target in targets:
            signature = self.signatures[target]
            for keyword in dict.fromkeys(keywords):
                if keyword.lower() in {"self", "cls"}:
                    continue
                if not signature.accepts(keyword):
                    return (
                        f"signature: {target} does not accept keyword {keyword!r}; "
                        f"declared parameters are {list(signature.parameters)[:12]}"
                    )
        return None

    # ---------------------------------------------------------------- verify
    def verify_claim(self, claim: str, top_k: int = 4) -> ClaimVerdict:
        """Decide supported, contradicted, or unsupported for one claim."""
        text = str(claim).strip()
        if not text:
            return ClaimVerdict("unsupported", text, "empty claim", 0.0)
        signature_failure = self.check_signature_claim(text)
        if signature_failure:
            return ClaimVerdict(
                "unsupported", text, signature_failure, 0.0, signature_rule=signature_failure
            )
        ranked = self.bm25(text, top_k=max(4, int(top_k)))
        if not ranked:
            return ClaimVerdict("unsupported", text, "no passage matched the claim", 0.0)
        rare = self.rare_terms(text)
        content = [
            term
            for term in extract_terms(text)
            if term not in STOPWORDS
            and len(term) >= 3
            and not term.replace(".", "").isdigit()
        ]
        claim_numbers = extract_numbers(text)
        # The evidence set is the top_k term-ranked passages, widened by any
        # deeper passage that both states one of the claim's quantities AND
        # shares at least two of its content terms. That widening is what
        # lets a composite sentence cite a metric table and a parameter count
        # from two adjacent paragraphs, while a number in an unrelated table
        # still cannot vote: it has no shared subject.
        selected = [index for _score, index in ranked]
        for _score, index in self.bm25(text, top_k=24):
            if index in selected:
                continue
            shared = sum(1 for term in set(content) if term in self.terms[index])
            states = any(number in self.numbers[index] for number in claim_numbers)
            if states and shared >= 2:
                selected.append(index)
        best_score = float(ranked[0][0])
        missing_terms: List[str] = []
        for term in rare:
            if not any(term in self.terms[index] for index in selected):
                missing_terms.append(term)
        if missing_terms:
            evidence = self._evidence_text(selected or [ranked[0][1]])
            return ClaimVerdict(
                "unsupported",
                text,
                f"rare term(s) absent from evidence: {missing_terms}",
                0.0,
                [self.passages[index].sha256 for index in (selected or [ranked[0][1]])],
                evidence,
                missing_terms=missing_terms,
            )
        # Rule 2: every number in the claim must appear in the evidence that
        # supports the claim's terms.
        evidence_indices = selected or [ranked[0][1]]
        missing_numbers: List[str] = [];
        found_numbers: List[str] = []
        for number in claim_numbers:
            if any(number in self.numbers[index] for index in evidence_indices):
                found_numbers.append(number)
            else:
                missing_numbers.append(number)
        evidence = self._evidence_text(evidence_indices)
        passages = [self.passages[index].sha256 for index in evidence_indices]
        if missing_numbers:
            contradicted = self._find_contradiction(text, evidence_indices, missing_numbers)
            status = "contradicted" if contradicted else "unsupported"
            reason = (
                f"quantity {contradicted} is stated differently in the evidence"
                if contradicted
                else f"number(s) absent from evidence: {missing_numbers}"
            )
            return ClaimVerdict(
                status,
                text,
                reason,
                0.0,
                passages,
                evidence,
                missing_numbers=missing_numbers,
                found_numbers=found_numbers,
            )
        coverage = float(len(found_numbers)) / max(len(claim_numbers), 1)
        confidence = min(1.0, 0.5 + 0.5 * coverage) * min(1.0, best_score / 12.0 + 0.4)
        return ClaimVerdict(
            "supported",
            text,
            "all rare terms and all quantities present in evidence",
            float(confidence),
            passages,
            evidence,
            found_numbers=found_numbers,
        )

    def _evidence_text(self, indices: Sequence[int], limit: int = 2400) -> str:
        parts = [self.passages[int(index)].text for index in indices[:4]]
        return chr(10).join(parts)[: int(limit)]

    def _find_contradiction(
        self,
        claim: str,
        indices: Sequence[int],
        missing: Sequence[str],
    ) -> str:
        """A number the evidence states differently for the same subject."""
        terms = [term for term in extract_terms(claim) if term not in STOPWORDS]
        for index in indices:
            passage = self.passages[int(index)]
            for sentence in re.split(r"(?<=[.!?])\s+", passage.text):
                lower = sentence.lower()
                hits = sum(1 for term in terms if term in lower)
                if hits < max(2, len(terms) // 2):
                    continue
                for number in extract_numbers(sentence):
                    for wanted in missing:
                        if wanted not in sentence and number != wanted:
                            return str(wanted)
        return ""

    # ------------------------------------------------------------- reporting
    def report(self) -> Dict[str, object]:
        return {
            "passages": len(self.passages),
            "signatures": len(self.signatures),
            "vocabulary": len(self.df),
            "rare_threshold": float(self.rare_threshold),
            "mean_passage_terms": float(self.mean_length),
            "corpus_digest": str(self.corpus_digest),
            "passage_digests": [passage.sha256[:16] for passage in self.passages[:8]],
        }


def build_verifier(root: str | Path = ".", **kwargs) -> OntologyVerifier:
    """Construct and build a verifier in one call."""
    verifier = OntologyVerifier(root=root, **kwargs)
    verifier.build()
    return verifier


# =========================================================================
# Directive S3: the TBAC-sandboxed exteroceptive corpus browser
# =========================================================================
class SandboxViolation(PermissionError):
    """Raised when a browser request leaves the allow-listed envelope."""


class SandboxedCorpusBrowser:
    """Read-only local corpus access under an explicit directory allow-list.

    The browser is the RUNTIME half of the two-tier grounding pipeline: when a
    Zone C query returns the C1 empty-retrieval veto (or an ungrounded topic),
    the caller asks the browser to read the allow-listed corpus, extract
    verified triples, crystallise them into Zone C as Tier-2 engrams, and
    answer from the passage that grounded them.

    The envelope is fail-closed and checked BEFORE any file is opened: a URL
    or scheme (http://, https://, file:, s3://) is refused, any '..' component
    is refused (traversal), a resolved path outside every allowed root is
    refused, and a non-file, a binary suffix or an oversized file is refused.

    Every accepted call returns a chained SHA-256 receipt over the roots, the
    query, the passages read and the engram ids written.
    """

    ALLOWED_SUFFIXES = (".md", ".txt", ".rst", ".json", ".csv", ".tsv", ".py", ".yaml", ".yml")
    FORBIDDEN_SCHEMES = ("http://", "https://", "ftp://", "file:", "s3://", "gs://", "//")

    def __init__(
        self,
        memory,
        roots,
        *,
        namespace: str = "corpus",
        max_file_bytes: int = 2_000_000,
        max_files: int = 512,
        extractor=None,
    ) -> None:
        resolved = []
        for root in roots:
            path = Path(root).expanduser().resolve()
            if path.is_dir():
                resolved.append(path)
        if not resolved:
            raise SandboxViolation("browser needs at least one existing allow-listed root")
        self.memory = memory
        self.roots = resolved
        self.namespace = str(namespace)
        self.max_file_bytes = int(max_file_bytes)
        self.max_files = int(max_files)
        self.extractor = extractor
        self.history = []
        self._previous = ""
        self.reads = 0
        self.writes = 0
        self.refusals = 0

    # ------------------------------------------------------------- envelope
    def resolve(self, candidate, *, must_exist: bool = True) -> Path:
        """Resolve one path inside the envelope, or raise SandboxViolation."""
        text = str(candidate).strip()
        lowered = text.lower()
        for scheme in self.FORBIDDEN_SCHEMES:
            if lowered.startswith(scheme):
                self.refusals += 1
                raise SandboxViolation(f"refused scheme: {scheme}")
        raw = Path(text)
        if ".." in raw.parts:
            self.refusals += 1
            raise SandboxViolation("refused path traversal: '..' component")
        if raw.is_absolute():
            resolved = raw.resolve()
        else:
            resolved = (self.roots[0] / raw).resolve()
        if not any(self._inside(resolved, root) for root in self.roots):
            self.refusals += 1
            raise SandboxViolation(f"refused path outside the allow-list: {resolved}")
        if must_exist and not resolved.exists():
            self.refusals += 1
            raise SandboxViolation(f"refused missing path: {resolved}")
        if must_exist and not resolved.is_file():
            self.refusals += 1
            raise SandboxViolation(f"refused non-file path: {resolved}")
        if must_exist and resolved.suffix.lower() not in self.ALLOWED_SUFFIXES:
            self.refusals += 1
            raise SandboxViolation(f"refused suffix: {resolved.suffix}")
        if must_exist and resolved.stat().st_size > self.max_file_bytes:
            self.refusals += 1
            raise SandboxViolation(f"refused oversized file: {resolved.stat().st_size} bytes")
        return resolved

    @staticmethod
    def _inside(path: Path, root: Path) -> bool:
        try:
            path.relative_to(root)
        except ValueError:
            return False
        return True

    def files(self):
        found = []
        for root in self.roots:
            for path in sorted(root.rglob("*")):
                if len(found) >= self.max_files:
                    return found
                if not path.is_file():
                    continue
                if path.suffix.lower() not in self.ALLOWED_SUFFIXES:
                    continue
                try:
                    if path.stat().st_size > self.max_file_bytes:
                        continue
                except OSError:
                    continue
                found.append(path)
        return found

    # ------------------------------------------------------------- retrieval
    @staticmethod
    def _terms(text: str):
        return [
            token
            for token in re.findall(r"[A-Za-z0-9_]+", str(text).lower())
            if len(token) > 2
        ]

    def scan(self, query: str, *, limit: int = 6):
        """Rank allow-listed passages against the query by term coverage."""
        wanted = set(self._terms(query))
        if not wanted:
            return []
        scored = []
        for path in self.files():
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            self.reads += 1
            offset = 0
            for line in text.splitlines():
                content = line.strip()
                offset += 1
                if not content:
                    continue
                terms = set(self._terms(content))
                if not terms:
                    continue
                overlap = len(wanted & terms)
                if overlap == 0:
                    continue
                scored.append(
                    {
                        "source": str(path),
                        "line": int(offset),
                        "text": content,
                        "score": float(overlap) / float(len(wanted)),
                        "overlap": int(overlap),
                    }
                )
        scored.sort(key=lambda row: (-float(row["score"]), str(row["source"]), int(row["line"])))
        # Keep at most two passages per source so one verbose file cannot fill
        # the whole evidence set.
        seen = {}
        kept = []
        for row in scored:
            count = seen.get(str(row["source"]), 0)
            if count >= 2:
                continue
            seen[str(row["source"])] = count + 1
            kept.append(row)
            if len(kept) >= int(limit):
                break
        return kept

    # ---------------------------------------------------------- crystallise
    def browse_and_crystallize(
        self,
        query: str,
        namespace=None,
        *,
        path=None,
        limit: int = 4,
        min_score: float = 0.34,
    ):
        """Ground a query in the allow-listed corpus and crystallise it.

        A query with no passage at or above min_score is NOT answered: it
        returns grounded=False and writes nothing, which is the fail-closed
        behaviour the C1 rule requires.
        """
        namespace = str(namespace or self.namespace)
        started = time.perf_counter()
        try:
            if path is not None:
                resolved = self.resolve(path)
                passages = []
                text = resolved.read_text(encoding="utf-8", errors="replace")
                wanted = set(self._terms(query))
                for offset, line in enumerate(text.splitlines(), start=1):
                    terms = set(self._terms(line))
                    if not terms or not wanted:
                        continue
                    overlap = len(wanted & terms)
                    if overlap:
                        passages.append(
                            {
                                "source": str(resolved),
                                "line": int(offset),
                                "text": line.strip(),
                                "score": float(overlap) / float(len(wanted)),
                                "overlap": int(overlap),
                            }
                        )
                passages.sort(key=lambda row: -float(row["score"]))
                passages = passages[: max(int(limit), 1)]
            else:
                passages = self.scan(query, limit=limit)
        except SandboxViolation as error:
            return {
                "grounded": False,
                "answered": False,
                "refused": True,
                "reason": str(error),
                "query": str(query),
                "written": 0,
                "receipt": "",
                "elapsed_ms": float((time.perf_counter() - started) * 1e3),
            }
        accepted = [row for row in passages if float(row["score"]) >= float(min_score)]
        if not accepted:
            self.history.append(
                {"query": str(query), "grounded": False, "written": 0}
            )
            return {
                "grounded": False,
                "answered": False,
                "refused": False,
                "reason": "no-grounded-passage",
                "query": str(query),
                "written": 0,
                "passages": passages,
                "receipt": "",
                "elapsed_ms": float((time.perf_counter() - started) * 1e3),
            }
        written_ids = []
        triples = []
        for row in accepted:
            text = str(row["text"])
            digest = hashlib.sha256(text.encode("utf-8")).hexdigest()
            if self.memory is not None:
                generator = np.random.default_rng(int(digest[:16], 16) % (2**63 - 1))
                dim = int(getattr(self.memory, "dim", 1024))
                raw = generator.standard_normal(dim) + 1j * generator.standard_normal(dim)
                wave = (raw / max(float(np.linalg.norm(raw)), 1e-12)).astype(np.complex64)
                record = self.memory.write(
                    wave,
                    label=int(digest[:6], 16) % 4096,
                    tier=2,
                    namespace=namespace,
                )
                written_ids.append(int(record.engram_id))
                self.writes += 1
            triples.extend(self._triples(str(row["source"]), int(row["line"]), text))
        answer = str(accepted[0]["text"])
        payload = {
            "query": str(query),
            "namespace": namespace,
            "sources": [str(row["source"]) for row in accepted],
            "lines": [int(row["line"]) for row in accepted],
            "passage_sha256": [
                hashlib.sha256(str(row["text"]).encode("utf-8")).hexdigest()
                for row in accepted
            ],
            "written": len(written_ids),
            "previous": self._previous,
        }
        receipt = hashlib.sha256(
            json.dumps(payload, sort_keys=True).encode("utf-8")
        ).hexdigest()
        self._previous = receipt
        self.history.append({"grounded": True, "receipt": receipt, **payload})
        return {
            "grounded": True,
            "answered": True,
            "refused": False,
            "reason": "",
            "query": str(query),
            "answer": answer,
            "passages": accepted,
            "triples": triples[:32],
            "engram_ids": written_ids,
            "written": len(written_ids),
            "receipt": receipt,
            "chain_length": len(self.history),
            "elapsed_ms": float((time.perf_counter() - started) * 1e3),
        }

    @staticmethod
    def _triples(source: str, line: int, text: str):
        """Deterministic (subject, relation, object) extraction from one line."""
        out = []
        separator = "=" if "=" in text and ":" not in text.split("=")[0] else ":"
        if separator in text:
            subject = text.split(separator, 1)[0].strip()
            rest = text.split(separator, 1)[1].strip()
            value = rest.split(",")[0].strip()
            if subject and value:
                out.append(
                    {
                        "subject": subject,
                        "relation": "has_value",
                        "object": value,
                        "source": str(source),
                        "line": str(int(line)),
                    }
                )
        return out

    def report(self):
        return {
            "roots": [str(root) for root in self.roots],
            "files_visible": int(len(self.files())),
            "reads": int(self.reads),
            "writes": int(self.writes),
            "refusals": int(self.refusals),
            "grounded_calls": int(sum(1 for row in self.history if row.get("grounded"))),
            "chain_length": int(len(self.history)),
            "head": str(self._previous),
        }

"""Foveated harmonic tape: constant read SNR as the tape grows (Sovereign T3a).

Slot 2 is partitioned into 16 disjoint harmonic comb sub-bands of 16 complex
channels. One page holds 16 cells, one cell owns one sub-band, so the inner
product between two cells of the same page is exactly zero up to float32
rounding. Only three contiguous pages live in the active window; outer pages
are committed to Zone C and paged back by a velocity-predicted prefetch.
"""

from __future__ import annotations

import hashlib
from typing import Dict, List, Optional, Sequence, Tuple

import numpy as np

D_SLOT = 256
B_PAGE = 16
D_CELL = D_SLOT // B_PAGE
_EPS = 1e-12


class HarmonicComb:
    """Disjoint 16-channel comb codes for one page of 16 cells."""

    def __init__(self, seed: int = 20261111, alphabet: Sequence[str] = ("0", "1", "#", "_")) -> None:
        self.seed = int(seed)
        self.alphabet = [str(symbol) for symbol in alphabet]
        generator = np.random.default_rng(self.seed)
        prototypes = generator.standard_normal((len(self.alphabet), D_CELL)) + 1j * generator.standard_normal(
            (len(self.alphabet), D_CELL)
        )
        norms = np.linalg.norm(prototypes, axis=1, keepdims=True)
        self.prototypes = prototypes / np.maximum(norms, _EPS)
        self.symbol_index = {symbol: index for index, symbol in enumerate(self.alphabet)}

    def embed(self, symbol: str, cell: int) -> np.ndarray:
        vector = np.zeros(D_SLOT, dtype=np.complex128)
        index = self.symbol_index.get(str(symbol), self.symbol_index.get("_", 0))
        start = int(cell) * D_CELL
        vector[start : start + D_CELL] = self.prototypes[index]
        return vector

    def page_wave(self, symbols: Sequence[str]) -> np.ndarray:
        wave = np.zeros(D_SLOT, dtype=np.complex128)
        for cell, symbol in enumerate(symbols[:B_PAGE]):
            wave = wave + self.embed(str(symbol), cell)
        return wave / np.sqrt(float(B_PAGE))

    def read(self, wave: np.ndarray, cell: int) -> Tuple[str, float]:
        start = int(cell) * D_CELL
        channel = np.asarray(wave[start : start + D_CELL], dtype=np.complex128)
        norm = float(np.linalg.norm(channel))
        if norm <= _EPS:
            return "_", 0.0
        alignment = np.real(self.prototypes.conj() @ channel) / norm
        best = int(np.argmax(alignment))
        second = float(np.max(np.delete(alignment, best))) if alignment.size > 1 else 0.0
        margin = float(alignment[best] - second)
        return self.alphabet[best], margin

    def decode(self, wave: np.ndarray) -> List[str]:
        return [self.read(wave, cell)[0] for cell in range(B_PAGE)]

    def cell_crosstalk(self, symbols: Sequence[str]) -> float:
        """Maximum inter-cell coherence. Disjoint sub-bands give exactly 0."""
        codes = np.stack(
            [self.embed(str(symbol), cell) for cell, symbol in enumerate(symbols[:B_PAGE])]
        )
        gram = np.abs(codes @ codes.conj().T) ** 2
        np.fill_diagonal(gram, 0.0)
        return float(np.sqrt(gram.max())) if gram.size else 0.0


class PagedHarmonicTape:
    """A 3-page fovea over an unbounded paged harmonic tape."""

    def __init__(
        self,
        *,
        memory=None,
        length: int = 256,
        alphabet: Sequence[str] = ("0", "1", "#", "_"),
        namespace: str = "tape_pages",
        seed: int = 20261111,
    ) -> None:
        self.length = int(length)
        self.alphabet = [str(symbol) for symbol in alphabet]
        self.memory = memory
        self.namespace = str(namespace)
        self.comb = HarmonicComb(seed=seed, alphabet=self.alphabet)
        self.pages: Dict[int, List[str]] = {}
        self.fovea: Dict[int, np.ndarray] = {}
        self.page_engram: Dict[int, int] = {}
        self.head = 0
        self.active_page = 0
        self.page_ins = 0
        self.page_outs = 0
        self.prefetches = 0
        self.moves = 0
        self.read_margins: List[float] = []
        for page in range(max(1, (self.length + B_PAGE - 1) // B_PAGE)):
            self.pages[page] = ["_"] * B_PAGE
        self._ensure_fovea(0)

    # --------------------------------------------------------------- pages
    def _page_wave(self, page: int) -> np.ndarray:
        return self.comb.page_wave(self.pages[page])

    def _ensure_fovea(self, page: int) -> None:
        for offset in (-1, 0, 1):
            index = int(page) + offset
            if index < 0 or index not in self.pages:
                continue
            if index in self.fovea:
                continue
            if self.memory is not None and index in self.page_engram:
                try:
                    wave = self.memory.fetch_wave(int(self.page_engram[index]))
                    self.fovea[index] = np.asarray(wave, dtype=np.complex128)
                    self.pages[index] = self.comb.decode(self.fovea[index])
                    self.page_ins += 1
                    continue
                except Exception:
                    pass
            self.fovea[index] = self._page_wave(index)
        # Evict pages outside the 3-page halo.
        for index in list(self.fovea):
            if abs(index - int(page)) > 1:
                self._page_out(index)
                self.fovea.pop(index, None)

    def _page_out(self, page: int) -> None:
        if self.memory is None:
            return
        wave = self._page_wave(page)
        try:
            record = self.memory.write(
                wave.astype(np.complex64), label=int(page), tier=2, namespace=self.namespace
            )
            self.page_engram[int(page)] = int(record.engram_id)
            self.page_outs += 1
        except Exception:
            pass

    def prefetch(self, velocity: int) -> None:
        if int(velocity) == 0:
            return
        target = int(self.active_page) + (1 if int(velocity) > 0 else -1) * 2
        if target in self.pages and target not in self.fovea:
            self._ensure_fovea(int(self.active_page))
            self.prefetches += 1

    # ---------------------------------------------------------------- head
    def page_of(self, cell: int) -> int:
        return int(cell) // B_PAGE

    def offset_of(self, cell: int) -> int:
        return int(cell) % B_PAGE

    def seek(self, cell: int) -> None:
        target = int(cell)
        velocity = 1 if target >= self.head else -1
        while self.head != target:
            self.move(velocity)

    def move(self, delta: int) -> None:
        target = self.head + int(delta)
        if target < 0 or target >= self.length:
            raise IndexError("head off tape")
        old_page = self.active_page
        self.head = target
        self.moves += 1
        self.active_page = self.page_of(target)
        if self.active_page != old_page:
            self._ensure_fovea(self.active_page)
            self.prefetch(int(delta))

    def read(self, cell: Optional[int] = None) -> str:
        if cell is not None:
            self.seek(int(cell))
        page = self.page_of(self.head)
        offset = self.offset_of(self.head)
        self._ensure_fovea(page)
        wave = self.fovea.get(page)
        if wave is None:
            return "_"
        symbol, margin = self.comb.read(wave, offset)
        self.read_margins.append(float(margin))
        return symbol

    def write(self, symbol: str, cell: Optional[int] = None) -> None:
        if cell is not None:
            self.seek(int(cell))
        page = self.page_of(self.head)
        offset = self.offset_of(self.head)
        self._ensure_fovea(page)
        self.pages[page][offset] = str(symbol)
        self.fovea[page] = self._page_wave(page)

    def tape_text(self) -> str:
        text = "".join(symbol for page in sorted(self.pages) for symbol in self.pages[page])
        return text[: self.length]

    def load(self, text: str) -> None:
        symbols = list(str(text)) + ["_"] * max(0, self.length - len(str(text)))
        for index, symbol in enumerate(symbols[: self.length]):
            page, offset = self.page_of(index), self.offset_of(index)
            self.pages.setdefault(page, ["_"] * B_PAGE)[offset] = symbol
        for page in list(self.fovea):
            self.fovea[page] = self._page_wave(page)

    # --------------------------------------------------------------- gates
    def intra_page_crosstalk(self) -> float:
        symbols = (self.alphabet * 4)[:B_PAGE]
        return float(self.comb.cell_crosstalk(symbols))

    def min_read_margin(self) -> float:
        return float(min(self.read_margins)) if self.read_margins else 0.0

    def stats(self) -> Dict[str, object]:
        return {
            "length": int(self.length),
            "pages": int(len(self.pages)),
            "page_capacity": int(B_PAGE),
            "d_slot": int(D_SLOT),
            "d_cell": int(D_CELL),
            "head": int(self.head),
            "page_ins": int(self.page_ins),
            "page_outs": int(self.page_outs),
            "prefetches": int(self.prefetches),
            "moves": int(self.moves),
            "reads": int(len(self.read_margins)),
            "min_read_margin": float(self.min_read_margin()),
            "intra_page_crosstalk": float(self.intra_page_crosstalk()),
        }


def reverse_tape(tape: PagedHarmonicTape, length: int) -> str:
    for index in range(int(length) // 2):
        left = tape.read(index)
        right = tape.read(int(length) - 1 - index)
        tape.write(right, index)
        tape.write(left, int(length) - 1 - index)
    return tape.tape_text()[: int(length)]


def palindrome_check(tape: PagedHarmonicTape, length: int) -> bool:
    for index in range(int(length) // 2):
        if tape.read(index) != tape.read(int(length) - 1 - index):
            return False
    return True


def binary_add(tape: PagedHarmonicTape, length: int) -> str:
    """Read A#B, write A#B#A+B on the paged tape."""
    text = "".join(tape.read(index) for index in range(int(length))).strip("_")
    if "#" not in text:
        raise ValueError("binary_add needs A#B")
    left, right = text.split("#", 1)
    left = left or "0"
    right = right.split("#", 1)[0] or "0"
    total = int(left, 2) + int(right, 2)
    result = bin(total)[2:]
    output = f"{left}#{right}#{result}"
    tape.load(output)
    return output

"""Demand-projected cellular sheaf over unannotated Python repositories (T4b).

A repository is a cellular sheaf (G, F): modules are vertices, imports and
calls are edges, and each edge carries a usage projector P_e = diag(r*)
built from the capability bits that the callee body actually dereferences.
The coboundary energy

    E_sheaf(s) = sum_e || P_e (r*_v - p_u) ||^2 + symbol + arity terms

is zero exactly when every caller provides every capability that the callee
demands.  An unannotated parameter is never a wildcard: its demand is read
from the operations inside the body and pulled back across the call graph.
"""

from __future__ import annotations

import ast
import hashlib
import itertools
import json
import math
import textwrap
from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Sequence, Set, Tuple

import numpy as np

CAP_NUM_ARITH = 0
CAP_INT_INDEX = 1
CAP_TEXT_OPS = 2
CAP_SIZED = 3
CAP_ITERABLE = 4
CAP_ELEM_NUM = 5
CAP_ELEM_TEXT = 6
CAP_ELEM_ATTR = 7
CAP_MAP_READ = 8
CAP_MAP_MUT = 9
CAP_SEQ_MUT = 10
CAP_SET_OPS = 11
CAP_CALLABLE = 12
CAP_HASHABLE = 13
CAP_NON_NONE = 14
CAP_CONFLICT = 15

CAP_NAMES = (
    "CAP_NUM_ARITH", "CAP_INT_INDEX", "CAP_TEXT_OPS", "CAP_SIZED",
    "CAP_ITERABLE", "CAP_ELEM_NUM", "CAP_ELEM_TEXT", "CAP_ELEM_ATTR",
    "CAP_MAP_READ", "CAP_MAP_MUT", "CAP_SEQ_MUT", "CAP_SET_OPS",
    "CAP_CALLABLE", "CAP_HASHABLE", "CAP_NON_NONE", "CAP_CONFLICT",
)
DIM = 16
ZERO = np.zeros(DIM, dtype=np.int64)


def vec(*caps: int) -> np.ndarray:
    out = ZERO.copy()
    for cap in caps:
        out[int(cap)] = 1
    return out


def names(vector: np.ndarray) -> List[str]:
    return [CAP_NAMES[index] for index in np.flatnonzero(np.asarray(vector))]


# ------------------------------------------------- static provision schema
TYPE_PROVISION: Dict[str, np.ndarray] = {
    "str": vec(CAP_TEXT_OPS, CAP_SIZED, CAP_ITERABLE, CAP_ELEM_TEXT, CAP_HASHABLE, CAP_NON_NONE),
    "bytes": vec(CAP_SIZED, CAP_ITERABLE, CAP_HASHABLE, CAP_NON_NONE),
    "int": vec(CAP_NUM_ARITH, CAP_INT_INDEX, CAP_HASHABLE, CAP_NON_NONE),
    "float": vec(CAP_NUM_ARITH, CAP_HASHABLE, CAP_NON_NONE),
    "bool": vec(CAP_NUM_ARITH, CAP_INT_INDEX, CAP_HASHABLE, CAP_NON_NONE),
    "list": vec(CAP_SIZED, CAP_ITERABLE, CAP_SEQ_MUT, CAP_NON_NONE),
    "tuple": vec(CAP_SIZED, CAP_ITERABLE, CAP_HASHABLE, CAP_NON_NONE),
    "dict": vec(CAP_SIZED, CAP_ITERABLE, CAP_MAP_READ, CAP_MAP_MUT, CAP_NON_NONE),
    "set": vec(CAP_SIZED, CAP_ITERABLE, CAP_SET_OPS, CAP_NON_NONE),
    "frozenset": vec(CAP_SIZED, CAP_ITERABLE, CAP_HASHABLE, CAP_NON_NONE),
    "None": ZERO.copy(),
}
ANNOTATION_NAMES = {
    "str": "str", "bytes": "bytes", "int": "int", "float": "float",
    "bool": "bool", "list": "list", "List": "list", "tuple": "tuple",
    "Tuple": "tuple", "dict": "dict", "Dict": "dict", "set": "set",
    "Set": "set", "frozenset": "frozenset", "None": "None",
}
ELEMENT_PROVISION = {
    "int": vec(CAP_ELEM_NUM), "float": vec(CAP_ELEM_NUM),
    "str": vec(CAP_ELEM_TEXT), "Attrs": vec(CAP_ELEM_ATTR),
}

METHOD_CAPS: Dict[str, int] = {
    "strip": CAP_TEXT_OPS, "split": CAP_TEXT_OPS, "lower": CAP_TEXT_OPS,
    "upper": CAP_TEXT_OPS, "replace": CAP_TEXT_OPS, "encode": CAP_TEXT_OPS,
    "startswith": CAP_TEXT_OPS, "endswith": CAP_TEXT_OPS, "format": CAP_TEXT_OPS,
    "get": CAP_MAP_READ, "keys": CAP_MAP_READ, "values": CAP_MAP_READ,
    "items": CAP_MAP_READ, "setdefault": CAP_MAP_MUT, "update": CAP_MAP_MUT,
    "pop": CAP_MAP_MUT, "append": CAP_SEQ_MUT, "extend": CAP_SEQ_MUT,
    "insert": CAP_SEQ_MUT, "sort": CAP_SEQ_MUT, "add": CAP_SET_OPS,
    "discard": CAP_SET_OPS, "union": CAP_SET_OPS, "intersection": CAP_SET_OPS,
    "join": CAP_ELEM_TEXT,
}
NUMERIC_CALLS = {"abs": CAP_NUM_ARITH, "float": CAP_NUM_ARITH,
                 "int": CAP_INT_INDEX, "round": CAP_NUM_ARITH}
ITERABLE_CALLS = {"sorted", "list", "set", "tuple", "min", "max", "iter",
                  "enumerate", "zip", "sum", "any", "all", "reversed"}


@dataclass
