LEXICON: Dict[str, List[Tuple[Cat, Frame]]] = {}


def _add(words: Sequence[str], cat: Cat, frame: Frame) -> None:
    for word in words:
        LEXICON.setdefault(str(word).lower(), []).append((cat, frame.copy()))


